# ==============================================================================
# PANEL ESCOLAR v7: ASISTENCIA + NOTAS (2025-2026) + DIAGNÓSTICO PDD + DIA
# Versión para Shinylive (WebAssembly). Guardar en UTF-8.
# Carga planillas Excel de asistencia, notas, PDD y DIA, las cruza por curso y
# alumno, y muestra KPIs, gráficos, perfiles individuales y riesgo integral.
# ==============================================================================

suppressPackageStartupMessages({
  library(shiny)
  library(bslib)
  library(readxl)
  library(dplyr)
  library(tidyr)
  library(ggplot2)
  library(scales)
  library(svglite)
  library(treemapify)
  library(ggrepel)
})

options(shiny.maxRequestSize = 60 * 1024^2)

# ==============================================================================
# CONSTANTES Y CONFIGURACIÓN
# Umbrales (asistencia 85%, nota roja 4.0), niveles de logro, orden de meses, colores y paletas.
# ==============================================================================
UMBRAL_ASIST <- 85
NOTA_ROJA    <- 4.0
# Niveles de logro PDD (Adecuado, Elemental, Insuficiente)
UMBRAL_LOGRO_ADEC <- 75L
UMBRAL_LOGRO_ELEM <- 60L
LV_ADEC <- sprintf("Adecuado (>=%d%%)", UMBRAL_LOGRO_ADEC)
LV_ELEM <- sprintf("Elemental (%d-%d%%)", UMBRAL_LOGRO_ELEM, UMBRAL_LOGRO_ADEC - 1L)
LV_INSU <- sprintf("Insuficiente (<%d%%)", UMBRAL_LOGRO_ELEM)
niveles_logro <- c(LV_ADEC, LV_ELEM, LV_INSU)
colores_logro <- stats::setNames(c("#2f6db5", "#f0a030", "#d64550"), niveles_logro)
# Niveles de logro DIA (Agencia de Calidad)
niveles_dia <- c("Nivel I (No logrado)", "Nivel II (Parcial)", "Nivel III (Satisfactorio)")
colores_dia <- stats::setNames(c("#d64550", "#f0a030", "#2f6db5"), niveles_dia)
meses_es <- c("01" = "Enero", "02" = "Febrero", "03" = "Marzo", "04" = "Abril",
              "05" = "Mayo", "06" = "Junio", "07" = "Julio", "08" = "Agosto",
              "09" = "Septiembre", "10" = "Octubre", "11" = "Noviembre", "12" = "Diciembre")
# ==============================================================================
# CATÁLOGO DE ASIGNATURAS
# Las 31 asignaturas del colegio y sus variantes de nombre (alias), para unificarlas entre planillas, PDD y DIA.
# ==============================================================================
UNIFICAR_ASIGNATURAS <- TRUE
ALIAS_ASIGNATURAS <- list(
  "Artes Visuales" = c(
    "ARTES VISUALES", "ARTES", "ARTE VISUAL", "ARTES VISUALES."
  ),
  "Biología Celular y Molecular" = c(
    "BIOLOGIA CELULAR Y MOLECULAR", "BIOLOGIA CELULAR", "BIOLOGIA MOLECULAR"
  ),
  "Ciencias Naturales" = c(
    "CIENCIAS NATURALES", "CIENCIAS", "CIENCIA NATURAL"
  ),
  "Ciencias de la Salud" = c(
    "CIENCIAS DE LA SALUD", "CIENCIAS DE LA SALUD.", "CIENCIA DE LA SALUD"
  ),
  "Ciencias para la Ciudadanía" = c(
    "CIENCIAS PARA LA CIUDADANIA", "CIENCIAS PARA LA CIUDADANIA.", "CIENCIA PARA LA CIUDADANIA"
  ),
  "Comprensión Histórica del Presente" = c(
    "COMPRENSION HISTORICA DEL PRESENTE", "COMPRENSION HISTORICA"
  ),
  "Historia, Geografía y Ciencias Sociales" = c(
    "HISTORIA GEOGRAFIA Y CIENCIAS SOCIALES",
    "HISTORIA, GEOGRAFIA Y CIENCIAS SOCIALES",
    "HISTORIA GEOGRAFIA Y CIENCIAS DE LA SALUD",
    "HISTORIA, GEOGRAFIA Y CIENCIAS DE LA SALUD",
    "HISTORIA"
  ),
  "Tecnología" = c(
    "TECNOLOGIA", "EDUCACION TECNOLOGICA"
  ),
  "Educación Ciudadana" = c(
    "EDUCACION CIUDADANA", "FORMACION CIUDADANA"
  ),
  "Educación Física y Salud" = c(
    "EDUCACION FISICA Y SALUD", "EDUCACION FISICA", "ED FISICA Y SALUD", "ED. FISICA Y SALUD"
  ),
  "Filosofía" = c(
    "FILOSOFIA"
  ),
  "Idioma Extranjero: Inglés" = c(
    "IDIOMA EXTRANJERO : INGLES", "IDIOMA EXTRANJERO: INGLES",
    "IDIOMA EXTRANJERO %58 INGLES", "IDIOMA EXTRANJERO%58 INGLES",
    "IDIOMA EXTRANJERO INGLES", "IDIOMA EXTRANJERO", "INGLES"
  ),
  "Taller de Inglés" = c(
    "TALLER DE INGLES", "TALLES DE INGLES", "TALLER INGLES"
  ),
  "Lectura y Escritura Especializadas" = c(
    "LECTURA Y ESCRITURA ESPECIALIZADAS", "LECTURA Y ESCRITURA ESPECIALIZADA"
  ),
  "Lengua y Literatura" = c(
    "LENGUA Y LITERATURA"
  ),
  "Lenguaje y Comunicación" = c(
    "LENGUAJE Y COMUNICACION", "LENGUA CASTELLANA Y COMUNICACION", "LENGUAJE", "LECTURA"
  ),
  "Matemática" = c(
    "MATEMATICA", "MATEMATICAS"
  ),
  "Música" = c(
    "MUSICA", "ARTES MUSICALES", "EDUCACION MUSICAL"
  ),
  "Probabilidades y Estadística Descriptiva e Inferencial" = c(
    "PROBABILIDADES Y ESTADISTICA DESCRIPTIVA DIFERENCIAL",
    "PROBABILIDADES Y ESTADISTICA DESCRIPTIVA E INFERENCIAL",
    "PROBABILIDADES Y ESTADISTICA DESCRIPTIVA",
    "PROBABILIDADES Y ESTADISTICA"
  ),
  "Química" = c(
    "QUIMICA"
  ),
  "Filosofía Política" = c(
    "FILOSOFIA POLITICA"
  ),
  "Taller de Expresión Corporal" = c(
    "TALLER DE EXPRESION CORPORAL", "TALLER EXPRESION CORPORAL"
  ),
  "Taller de Lectura Comprensiva" = c(
    "TALLER DE LECTURA COMPRENSIVA", "TALLES DE LECTURA COMPRENSIVA", "TALLER LECTURA COMPRENSIVA"
  ),
  "Taller de Resolución de Problemas" = c(
    "TALLER DE RESOLUCION DE PROBLEMAS", "TALLER RESOLUCION DE PROBLEMAS"
  ),
  "Seminario de Filosofía" = c(
    "SEMINARIO DE FILOSOFIA"
  ),
  "Geografía, Territorio y Desafíos Socioambientales" = c(
    "GEOGRAFIA, TERRITORIO Y DESAFIOS SOCIOAMBIENTALES",
    "GEOGRAFIA TERRITORIO Y DESAFIOS SOCIOAMBIENTALES"
  ),
  "Física" = c(
    "FISICA"
  ),
  "Límites, Derivadas e Integrales" = c(
    "LIMITES, DERIVADAS E INTEGRALES", "LIMITES DERIVADAS E INTEGRALES"
  ),
  "Participación y Argumentación en Democracia" = c(
    "PARTICIPACION Y ARGUMENTACION EN DEMOCRACIA"
  ),
  "Comunes" = c(
    "COMUNES", "PLAN COMUN"
  )
)
orden_meses <- c("marzo", "abril", "mayo", "junio", "julio",
                 "agosto", "septiembre", "octubre", "noviembre", "diciembre")
col_azul <- "#2f6db5"
col_rojo <- "#d64550"
niveles_rango <- c("< 4.0", "4.0-4.9", "5.0-5.9", "6.0-7.0")
colores_rango <- c("< 4.0" = "#d64550", "4.0-4.9" = "#f0a030",
                   "5.0-5.9" = "#7fb3e0", "6.0-7.0" = "#1e4f8f")
niveles_asist <- c("Destacada (>=95%)", "Normal (90-94%)",
                   "En riesgo (85-89%)", "Critica (<85%)")
colores_asist <- stats::setNames(c("#1e4f8f", "#7fb3e0", "#f0a030", "#d64550"), niveles_asist)
paleta_cat <- c("#2f6db5", "#14a3a0", "#f0a030", "#8e6bbf", "#d64550",
                "#6c8a3e", "#1e4f8f", "#c0508f", "#7fb3e0", "#8a6d3b",
                "#3b82f6", "#10b981", "#f59e0b", "#ef4444", "#8b5cf6",
                "#ec4899", "#06b6d4", "#84cc16", "#f97316", "#6366f1",
                "#14b8a6", "#eab308", "#dc2626", "#7c3aed", "#db2777",
                "#0284c7", "#65a30d", "#ea580c", "#4f46e5", "#0d9488", "#ca8a04")
# ==============================================================================
# FUNCIONES AUXILIARES
# Utilidades: clasificar notas y asistencia, normalizar texto y nombres, reconocer cursos y emparejar alumnos entre fuentes.
# ==============================================================================
# Asigna una nota (1.0-7.0) a su rango: <4.0, 4.0-4.9, 5.0-5.9 o 6.0-7.0.
rangos_nota <- function(x) {
  cut(x, breaks = c(0, 4, 5, 6, 7.1), right = FALSE, labels = niveles_rango)
}
# Etiqueta una nota como Deficiente, Baja, Decente o Alta.
clasificar_desempeno_nota <- function(x) {
  case_when(
    is.na(x) ~ NA_character_,
    x < 4.0  ~ "Deficiente / Roja (< 4.0)",
    x < 5.0  ~ "Baja / En riesgo (4.0 - 4.9)",
    x < 6.0  ~ "Decente / Adecuada (5.0 - 5.9)",
    TRUE     ~ "Alta / Destacada (6.0 - 7.0)"
  )
}
# Clasifica un % de logro PDD en Adecuado, Elemental o Insuficiente.
clasificar_logro <- function(x) {
  out <- ifelse(x >= UMBRAL_LOGRO_ADEC, LV_ADEC,
                ifelse(x >= UMBRAL_LOGRO_ELEM, LV_ELEM, LV_INSU))
  out[is.na(x)] <- NA_character_
  out
}
# Clasifica un % de asistencia: Destacada, Normal, En riesgo o Crítica.
categoria_asistencia <- function(p) {
  r <- cut(p, breaks = c(-Inf, UMBRAL_ASIST, 90, 95, Inf), right = FALSE,
           labels = rev(niveles_asist))
  factor(as.character(r), levels = niveles_asist)
}
# Calcula la mayor racha de inasistencias seguidas.
racha_max <- function(x) {
  if (length(x) == 0 || !any(x, na.rm = TRUE)) return(0L)
  r <- rle(as.logical(x))
  as.integer(max(r$lengths[r$values %in% TRUE]))
}
# Repara texto con codificación dañada (por ejemplo "MuÃ±oz" pasa a "Muñoz").
reparar_mojibake <- function(x) {
  x <- as.character(x)
  hay <- !is.na(x) & grepl("[\u00c3\u00e3\u00c2]", x)
  if (!any(hay)) return(x)
  pares <- c(
    "\u00c3\u00a1" = "\u00e1", "\u00c3\u00a9" = "\u00e9", "\u00c3\u00ad" = "\u00ed",
    "\u00c3\u00b3" = "\u00f3", "\u00c3\u00ba" = "\u00fa", "\u00c3\u00b1" = "\u00f1",
    "\u00c3\u00bc" = "\u00fc", "\u00c3\u0081" = "\u00c1", "\u00c3\u0089" = "\u00c9",
    "\u00c3\u2030" = "\u00c9", "\u00c3\u008d" = "\u00cd", "\u00c3\u0093" = "\u00d3",
    "\u00c3\u201c" = "\u00d3", "\u00c3\u009a" = "\u00da", "\u00c3\u0161" = "\u00da",
    "\u00c3\u0091" = "\u00d1", "\u00c3\u2018" = "\u00d1",
    "\u00c2\u00b0" = "\u00b0", "\u00c2\u00ba" = "\u00ba", "\u00c2\u00aa" = "\u00aa",
    "\u00c2\u00a0" = " "
  )
  bajas <- pares[startsWith(names(pares), "\u00c3")]
  pares <- c(pares, stats::setNames(unname(bajas), sub("^\u00c3", "\u00e3", names(bajas))))
  for (k in seq_along(pares)) x[hay] <- gsub(names(pares)[k], pares[[k]], x[hay], fixed = TRUE)
  x[hay] <- gsub("\u00c3", "\u00ed", x[hay], fixed = TRUE)
  x
}
# Normaliza texto: mayúsculas, sin tildes ni símbolos de ordinal.
norm_txt <- function(x) {
  d <- dim(x)
  x <- as.character(x)
  x <- gsub("%58", ":", x, fixed = TRUE)
  x <- reparar_mojibake(x)
  x <- toupper(trimws(x))
  x <- chartr("ÁÉÍÓÚÜÑÀÈÌÒÙÂÊÎÔÛ", "AEIOUUNAEIOUAEIOU", x)
  res <- gsub("[º°ª]", "", x)
  if (!is.null(d)) dim(res) <- d
  res
}
# Normaliza un nombre de persona para poder compararlo.
norm_nombre <- function(x) {
  x <- norm_txt(x)
  x <- gsub("[^A-Z ]", " ", x)
  trimws(gsub("\\s+", " ", x))
}
# Uniforma nombres ("Apellidos, Nombres" o "Apellidos Nombres") a formato título.
limpiar_nombre_persona <- function(x) {
  if (length(x) == 0) return(character(0))
  vapply(as.character(x), function(s) {
    if (is.na(s) || !nzchar(trimws(s))) return("")
    s <- reparar_mojibake(trimws(gsub("\\s+", " ", s)))
    if (grepl(",", s, fixed = TRUE)) {
      partes <- strsplit(s, ",", fixed = TRUE)[[1]]
      if (length(partes) >= 2) {
        s <- paste(trimws(partes[1]), trimws(paste(partes[-1], collapse = " ")))
      }
    }
    tools::toTitleCase(tolower(trimws(gsub("\\s+", " ", s))))
  }, character(1), USE.NAMES = FALSE)
}
# Convierte texto en una nota válida (1.0 a 7.0) y descarta valores fuera de rango.
num_nota <- function(x) {
  v <- suppressWarnings(as.numeric(gsub(",", ".", x)))
  idx <- !is.na(v) & v >= 10 & v <= 70
  v[idx] <- v[idx] / 10
  v[!is.na(v) & (v < 1.0 | v > 7.0)] <- NA
  round(v, 1)
}
# Indica si un texto parece un nombre de alumno (descarta cabeceras, totales y promedios).
es_nombre_alumno <- function(x) {
  if (length(x) == 0) return(logical(0))
  t <- norm_txt(x)
  es_cabecera <- grepl(
    "^(ALUMN[OA]S?|ESTUDIANTES?|NOMBRE DEL ESTUDIANTE|NOMBRES?|APELLIDOS?( Y NOMBRES?)?|PONDERACI[OÓ]N(ES)?|COEF(ICIENTE)?S?|PUNTAJES?|PROMEDIOS?|TOTALES?|RESUMEN|PORCENTAJES?|METAS?|CURSO|CURSO/S|DOCENTE|PROFESOR(A)?|PROFESSORA|ASIGNATURA|NOTA|EXAMEN|PARCIALES)$",
    t
  )
  es_meta <- grepl(
    "^(PROMEDIO|TOTAL|RESUMEN|PORCENTAJE|META|DIAS LECTIVOS|DIAS TRABAJADOS|#REF|#N/A|#VALOR|#DIV|RESUMEN DE OFERTA|LISTADO EMITIDO|PAGINA:|FECHA:|CREACION CHILLAN|YERBAS BUENAS)",
    t
  )
  tiene_letras <- grepl("[A-Z]{2}", t)
  nzchar(trimws(x)) & nchar(trimws(x)) > 3 & !es_cabecera & !es_meta & tiene_letras
}
# Detecta si un texto corresponde al semestre 1 o 2.
detectar_semestre <- function(txt) {
  t <- norm_txt(txt)
  if (length(t) == 0 || is.na(t)) return(NA_integer_)
  if (grepl("SEGUNDO|2\\s*[A-Z]{0,2}\\s*-?\\sSEM|SEM[A-Z]\\s*[-_ ]2([^0-9]|$)|\\(2A\\)|\\b2A\\b|\\(2-SEM\\)", t)) return(2L)
  if (grepl("PRIMER|1\\s[A-Z]{0,2}\\s*-?\\sSEM|SEM[A-Z]\\s*[-_ ]*1([^0-9]|$)|\\(1A\\)|\\b1A\\b|\\(1-SEM\\)", t)) return(1L)
  NA_integer_
}
# Unifica una asignatura con su nombre oficial del catálogo.
aplicar_alias <- function(asig, forzar = FALSE) {
  if (is.null(asig) || length(asig) == 0 || is.na(asig)) return("General")
  asig_clean <- gsub("%58", ":", as.character(asig), fixed = TRUE)
  if (!UNIFICAR_ASIGNATURAS && !forzar) return(asig_clean)
  k <- trimws(gsub("[.,:]", " ", norm_txt(asig_clean)))
  k <- trimws(gsub("\\s+", " ", k))
  for (nm in names(ALIAS_ASIGNATURAS)) {
    patrones <- trimws(gsub("\\s+", " ", gsub("[.,:]", " ", ALIAS_ASIGNATURAS[[nm]])))
    if (k %in% patrones) return(nm)
  }
  for (nm in names(ALIAS_ASIGNATURAS)) {
    patrones <- trimws(gsub("\\s+", " ", gsub("[.,:]", " ", ALIAS_ASIGNATURAS[[nm]])))
    for (p in patrones) {
      if (nchar(p) >= 6 && grepl(paste0("\\b", p, "\\b"), k)) return(nm)
    }
  }
  tools::toTitleCase(tolower(trimws(gsub("\\s+", " ", asig_clean))))
}
# Entrega la asignatura unificada, para cruzar notas con PDD y DIA.
asig_clave <- function(x) {
  if (length(x) == 0) return(character(0))
  res <- vapply(as.character(x), aplicar_alias, character(1), forzar = TRUE, USE.NAMES = FALSE)
  res <- ifelse(res %in% c("Lengua y Literatura", "Lenguaje y Comunicación", "Lectura y Escritura Especializadas", "Taller de Lectura Comprensiva"), "Lenguaje", res)
  res <- ifelse(res %in% c("Historia, Geografía y Ciencias Sociales", "Comprensión Histórica del Presente", "Educación Ciudadana"), "Historia", res)
  res <- ifelse(res %in% c("Ciencias Naturales", "Biología Celular y Molecular", "Ciencias de la Salud", "Ciencias para la Ciudadanía", "Física", "Química"), "Ciencias", res)
  res <- ifelse(res %in% c("Idioma Extranjero: Inglés", "Taller de Inglés"), "Inglés", res)
  res
}
# Reconoce el curso (número, básico/medio y letra) en un texto o nombre de archivo.
parsear_curso <- function(texto) {
  if (is.null(texto) || length(texto) == 0 || is.na(texto[1]) || !nzchar(as.character(texto)[1])) return(NULL)
  t_raw <- norm_txt(tools::file_path_sans_ext(texto[1]))
  t_raw <- gsub("%58", " ", t_raw, fixed = TRUE)
  t <- gsub("\\(.*?\\)", " ", t_raw)
  t <- gsub("-[0-9]{4,}.$", " ", t)
  t <- gsub("(?i)SEMESTRE\\s[0-9]?[A-Z]?", " ", t, perl = TRUE)
  m_rom <- regexec("(?:^|[\\s_-])(IV|III|II|I)(?:[\\s_-]+([A-Z]))?(?:$|[^A-Z0-9])", t, perl = TRUE)
  r_rom <- regmatches(t, m_rom)[[1]]
  if (length(r_rom) >= 2 && nzchar(r_rom[2]) &&
      (grepl("HC|TP|MEDI", t_raw) || grepl("^\\s*(IV|III|II|I)\\s+[A-Z]", t) || grepl("(IV|III|II|I)[A-Z]", t_raw))) {
    rom_map <- c("I" = 1L, "II" = 2L, "III" = 3L, "IV" = 4L)
    letra <- if (length(r_rom) >= 3) r_rom[3] else ""
    return(list(num = unname(rom_map[r_rom[2]]), tipo = "M", letra = letra))
  }
  t <- gsub("([0-9]{1,2})(ERO|RO|DO|TO|MO|VO)", "\\1", t)
  tipo <- ifelse(grepl("\\b(MEDI[OA]S?)\\b|HC|TP", t_raw), "M", "B")
  m <- regexec("\\b([1-8])\\s*([A-Z])?\\s*(?:BASIC[OA]S?|MEDI[OA]S?)\\b(?:\\s*[-_ ]?\\s*([A-Z])\\b)?",
               t, perl = TRUE)
  r <- regmatches(t, m)[[1]]
  if (length(r) >= 2 && nzchar(r[2])) {
    letra <- ""
    if (length(r) >= 3 && nzchar(r[3])) letra <- r[3]
    else if (length(r) >= 4 && nzchar(r[4])) letra <- r[4]
    return(list(num = as.integer(r[2]), tipo = tipo, letra = letra))
  }
  m_guion <- regexec("\\b([1-8])\\s*-\\s*([A-D])\\b", t, perl = TRUE)
  r_guion <- regmatches(t, m_guion)[[1]]
  if (length(r_guion) >= 3 && nzchar(r_guion[2])) {
    return(list(num = as.integer(r_guion[2]), tipo = tipo, letra = r_guion[3]))
  }
  m2 <- regexec("\\b([1-8])[\\s_-]*([A-D])?\\b", t, perl = TRUE)
  r2 <- regmatches(t, m2)[[1]]
  if (length(r2) >= 2 && nzchar(r2[2])) {
    letra <- if (length(r2) >= 3) r2[3] else ""
    return(list(num = as.integer(r2[2]), tipo = tipo, letra = letra))
  }
  NULL
}
# Escribe un curso reconocido en formato legible, por ejemplo "8° BÁSICO A".
etiqueta_curso <- function(p) {
  if (is.null(p)) return("")
  paste0(p$num, "° ", ifelse(p$tipo == "M", "MEDIO", "BÁSICO"),
         ifelse(nzchar(p$letra), paste0(" ", p$letra), ""))
}
# Igual que etiqueta_curso, pero sin fallar con valores vacíos o desconocidos.
etiqueta_curso_segura <- function(x) {
  if (is.null(x) || is.na(x) || !nzchar(as.character(x))) return("Sin Curso")
  p <- parsear_curso(x)
  if (is.null(p)) return(as.character(x))
  e <- etiqueta_curso(p)
  if (grepl("solo notas", x, ignore.case = TRUE)) e <- paste(e, "(solo notas)")
  e
}
# Aplica etiqueta_curso_segura a un vector de cursos.
etiquetar <- function(x) {
  x <- as.character(x)
  if (length(x) == 0) return(character(0))
  u <- unique(x)
  lab <- vapply(u, etiqueta_curso_segura, character(1), USE.NAMES = FALSE)
  unname(stats::setNames(lab, u)[x])
}
# Busca a qué curso con asistencia corresponde un curso de otra fuente.
emparejar_curso <- function(p, cursos_asist) {
  if (is.null(p) || length(cursos_asist) == 0) return(NA_character_)
  for (nm in cursos_asist) {
    q <- parsear_curso(nm)
    if (is.null(q)) next
    if (q$num == p$num && q$tipo == p$tipo && q$letra == p$letra && nzchar(p$letra)) {
      return(nm)
    }
  }
  for (nm in cursos_asist) {
    q <- parsear_curso(nm)
    if (is.null(q)) next
    if (q$num == p$num && q$tipo == p$tipo && (!nzchar(q$letra) || !nzchar(p$letra))) {
      return(nm)
    }
  }
  NA_character_
}
# Vincula cada alumno de una fuente con su equivalente en otra, sin repetir (tolera tildes y segundos nombres).
emparejar_uno_a_uno <- function(nombres_asist, nombres_notas) {
  res <- stats::setNames(rep(NA_character_, length(nombres_notas)), nombres_notas)
  if (length(nombres_asist) == 0 || length(nombres_notas) == 0) return(res)
  ta <- strsplit(norm_nombre(limpiar_nombre_persona(nombres_asist)), " ")
  tn <- strsplit(norm_nombre(limpiar_nombre_persona(nombres_notas)), " ")
  cand <- list()
  tok_igual <- function(x, y) {
    if (x == y) return(TRUE)
    if (nchar(x) >= 5 && nchar(y) >= 5 && abs(nchar(x) - nchar(y)) <= 1) {
      return(utils::adist(x, y)[1, 1] <= 1)
    }
    FALSE
  }
  n_coinc <- function(a, n) {
    sum(vapply(a, function(t) any(vapply(n, function(u) tok_igual(t, u), logical(1))), logical(1)))
  }
  for (i in seq_along(ta)) {
    for (j in seq_along(tn)) {
      a <- ta[[i]]; n <- tn[[j]]
      if (length(a) < 2 || length(n) < 2) next
      inter <- n_coinc(a, n)
      minl <- min(length(a), length(n))
      p1 <- tok_igual(a[1], n[1])
      p2 <- p1 && tok_igual(a[2], n[2])
      ok <- (inter >= minl) || (inter / minl >= 0.66 && p1) || (inter >= 2 && p1 && p2)
      if (!ok) next
      sc <- min(inter, max(length(a), length(n))) / max(length(a), length(n)) +
        ifelse(p1, 0.35, 0) +
        ifelse(p2, 0.35, 0)
      cand[[length(cand) + 1]] <- c(i = i, j = j, s = sc)
    }
  }
  if (length(cand) == 0) return(res)
  cm <- do.call(rbind, cand)
  cm <- cm[order(-cm[, "s"]), , drop = FALSE]
  usado_a <- rep(FALSE, length(ta))
  usado_n <- rep(FALSE, length(tn))
  for (k in seq_len(nrow(cm))) {
    i <- cm[k, "i"]; j <- cm[k, "j"]
    if (!usado_a[i] && !usado_n[j]) {
      res[j] <- nombres_asist[i]
      usado_a[i] <- TRUE
      usado_n[j] <- TRUE
    }
  }
  res
}
# Deduce la asignatura a partir del nombre del archivo.
extraer_asignatura <- function(nombre_archivo) {
  base <- tools::file_path_sans_ext(nombre_archivo)
  base <- gsub("%58", ":", base, fixed = TRUE)
  nn <- norm_txt(base)
  m_pos <- regexpr("\\b[0-9]{1,2}\\s*[A-Z]?\\s*(?:B[AÁ]SIC[OA]S?|MED[IÍ][OA]S?)\\b(?:\\s+[A-Z]\\b)?", nn, perl = TRUE)
  if (m_pos > 1) {
    asig <- substr(base, 1, m_pos - 1)
  } else if (m_pos == 1) {
    match_len <- attr(m_pos, "match.length")
    resto <- substr(base, match_len + 1, nchar(base))
    resto <- gsub("(?i)(SEMESTRE|SEM|NOTAS|PLANILLA|PRIMER|SEGUNDO).*", "", resto, perl = TRUE)
    resto <- gsub("[-_0-9]+", " ", resto)
    asig <- trimws(resto)
  } else {
    asig <- base
  }
  asig <- gsub("(?i)(SEGUNDO|PRIMER|1ER|2DO|SEMESTRE|NOTAS|PLANILLA).*", "", asig, perl = TRUE)
  asig <- gsub("[-_0-9]+", " ", asig)
  asig <- tools::toTitleCase(tolower(trimws(gsub("\\s+", " ", asig))))
  if (!nzchar(asig) || nchar(asig) < 3) asig <- "General"
  aplicar_alias(asig)
}
# Encuentra la fila y columna donde empieza la lista de alumnos.
detectar_encabezado <- function(nm) {
  exacto <- c("ALUMNOS", "ALUMNO", "ESTUDIANTES", "ESTUDIANTE", "NOMBRE",
              "NOMBRES", "APELLIDOS Y NOMBRES", "NOMBRE DEL ESTUDIANTE")
  f <- which(apply(nm, 1, function(r) any(r %in% exacto)))
  if (length(f) > 0) {
    c_nom <- which(nm[f[1], ] %in% exacto)[1]
    return(list(fila = f[1], col = c_nom))
  }
  f <- which(apply(nm, 1, function(r) any(grepl("^(ALUMN|ESTUDI|APELLID|NOMBR)", r))))
  if (length(f) == 0) return(NULL)
  c_nom <- which(grepl("^(ALUMN|ESTUDI|APELLID|NOMBR)", nm[f[1], ]))[1]
  list(fila = f[1], col = c_nom)
}
# Escribe un CSV listo para abrir en Excel.
escribir_csv_excel <- function(df, file) {
  txt <- utils::capture.output(utils::write.csv2(df, row.names = FALSE))
