# ==============================================================================
# LECTURA DE ASISTENCIA
# Lee los Excel de asistencia mensual (una hoja por mes) y entrega un registro por alumno y día (Asistió / Faltó).
# ==============================================================================
# Lee un Excel de asistencia mensual y devuelve un registro por alumno y día.
leer_asistencia_archivo <- function(ruta, nombre_archivo) {
  info <- parsear_curso(nombre_archivo)
  if (is.null(info)) stop("no pude identificar el curso en el nombre del archivo")
  curso <- etiqueta_curso(info)
  hojas <- readxl::excel_sheets(ruta)
  hojas_meses <- hojas[tolower(trimws(hojas)) %in% orden_meses]
  if (length(hojas_meses) == 0) {
    hojas_meses <- hojas[!grepl("(?i)(instruccion|portada|acumulad|resumen|grafic)", hojas, perl = TRUE)]
  }
  if (length(hojas_meses) == 0) stop("no se encontraron hojas de asistencia")
  datos_totales <- list()
  for (h in hojas_meses) {
    raw <- suppressMessages(read_excel(ruta, sheet = h, col_names = FALSE,
                                       col_types = "text", .name_repair = "minimal"))
    m <- as.matrix(raw)
    m[is.na(m)] <- ""
    m[] <- trimws(m)
    nm <- m
    nm[] <- norm_txt(m)
    enc <- detectar_encabezado(nm)
    if (is.null(enc) || is.na(enc$col)) next
    fila_h <- enc$fila
    c_nom <- enc$col
    if (fila_h >= nrow(m)) next
    
    filas_posibles <- (fila_h + 1):nrow(m)
    filas <- filas_posibles[es_nombre_alumno(m[filas_posibles, c_nom])]
    if (length(filas) < 3) next
    
    nombres <- limpiar_nombre_persona(m[filas, c_nom])
    mes_actual <- tolower(trimws(h))
    if (!mes_actual %in% orden_meses) {
      cab_txt <- tolower(paste(nm[1:fila_h, ], collapse = " "))
      for (mn in orden_meses) {
        if (grepl(paste0("\\b", mn, "\\b"), cab_txt)) { mes_actual <- mn; break }
      }
    }
    
    cols_resumen <- which(apply(nm[seq_len(min(fila_h + 1, nrow(nm))), , drop = FALSE], 2, function(col_txt) {
      any(grepl("TOTAL|AUSENTE|ASISTENCIA|META|%|PORC", col_txt))
    }))
    cols_asist <- setdiff(which(seq_len(ncol(m)) > c_nom), cols_resumen)
    dias_hdr_num <- suppressWarnings(as.integer(m[fila_h, cols_asist]))
    if (sum(!is.na(dias_hdr_num) & dias_hdr_num >= 1 & dias_hdr_num <= 31) >= 5) {
      cols_asist <- cols_asist[!is.na(dias_hdr_num) & dias_hdr_num >= 1 & dias_hdr_num <= 31]
    }
    if (length(cols_asist) == 0) next
    
    sub_m  <- m[filas, cols_asist, drop = FALSE]
    sub_nm <- nm[filas, cols_asist, drop = FALSE]
    
    sub_estado <- matrix(NA_character_, nrow = nrow(sub_m), ncol = ncol(sub_m))
    sub_estado[grepl("^(A|ASIST|ASISTIO|PRESENTE|P|1|1\\.0|•|\\*)$", sub_nm)] <- "Asistió"
    sub_estado[grepl("^(F|FALTO|AUSENTE|INASISTENTE|I|0|0\\.0|J|JUSTIFICADO)$", sub_nm)] <- "Faltó"
    
    idx <- which(!is.na(sub_estado), arr.ind = TRUE)
    if (nrow(idx) > 0) {
      real_col <- cols_asist[idx[, 2]]
      dia_hdr <- m[fila_h, real_col]
      dia <- ifelse(nzchar(dia_hdr), dia_hdr, as.character(real_col))
      datos_totales[[length(datos_totales) + 1]] <- data.frame(
        Nombre = nombres[idx[, 1]],
        Mes = mes_actual,
        Dia = dia,
        Valor = sub_m[idx],
        Estado = sub_estado[idx],
        Curso = curso,
        stringsAsFactors = FALSE
      )
    }
  }
  if (length(datos_totales) == 0) stop("no encontré registros de asistencia válidos")
  bind_rows(datos_totales)
}
# ==============================================================================
# LECTURA DE NOTAS
# Lee planillas de notas: detecta año, semestre, profesor, asignatura, curso y alumnos, y separa evaluaciones de promedios.
# ==============================================================================
# Tabla vacía de evaluaciones individuales.
det_cols_vacio <- function() {
  data.frame(Nombre_Notas = character(), Anio = integer(), Semestre = integer(),
             Profesor = character(), Evaluacion = integer(), Evaluacion_Nombre = character(),
             Tipo_Eval = character(), Nota = numeric(), Etiqueta = character(),
             Asignatura = character(), stringsAsFactors = FALSE)
}
# Tabla vacía de promedios.
prom_cols_vacio <- function() {
  data.frame(Nombre_Notas = character(), Anio = integer(), Semestre = integer(),
             Profesor = character(), Promedio = numeric(),
             Asignatura = character(), stringsAsFactors = FALSE)
}
# Lee una planilla de notas y devuelve evaluaciones, promedios y alumnos.
leer_notas_archivo <- function(ruta, nombre_archivo) {
  raw <- suppressMessages(read_excel(ruta, sheet = 1, col_names = FALSE,
                                     col_types = "text", .name_repair = "minimal"))
  m <- as.matrix(raw)
  m[is.na(m)] <- ""
  m[] <- trimws(m)
  nm <- m
  nm[] <- norm_txt(m)
  anio_archivo <- NA_integer_
  f_ce <- which(apply(nm[seq_len(min(15, nrow(nm))), , drop = FALSE], 1, function(r) any(grepl("CURSO ESCOLAR|ANO ESCOLAR|AÑO ESCOLAR", r))))
  if (length(f_ce) > 0) {
    r0 <- f_ce[1]
    c0 <- which(grepl("CURSO ESCOLAR|ANO ESCOLAR|AÑO ESCOLAR", nm[r0, ]))[1]
    ventana <- m[seq(r0, min(nrow(m), r0 + 4)), seq(max(1, c0 - 1), min(ncol(m), c0 + 1))]
    m_yr <- regmatches(ventana, regexec("^(202[4-9])$", trimws(ventana)))
    yrs <- unlist(lapply(m_yr, function(x) if (length(x) >= 2) x[2] else character(0)))
    if (length(yrs) > 0) anio_archivo <- as.integer(yrs[1])
  }
  if (is.na(anio_archivo)) {
    for (r in seq_len(min(15, nrow(m)))) {
      vals <- m[r, ]
      hit <- vals[grepl("^202[4-9]$", vals)]
      if (length(hit) > 0) { anio_archivo <- as.integer(hit[1]); break }
    }
  }
  if (is.na(anio_archivo)) {
    base_limpia <- gsub("-[0-9]{6,}.*$", "", nombre_archivo)
    m_a <- regmatches(base_limpia, regexec("\\b(202[4-9])\\b", base_limpia))[[1]]
    anio_archivo <- if (length(m_a) >= 2) as.integer(m_a[2]) else as.integer(format(Sys.Date(), "%Y"))
  }
  sem_archivo <- detectar_semestre(tools::file_path_sans_ext(nombre_archivo))
  if (is.na(sem_archivo)) {
    for (r in seq_len(min(10, nrow(m)))) {
      s <- detectar_semestre(paste(m[r, ], collapse = " "))
      if (!is.na(s)) { sem_archivo <- s; break }
    }
  }
  if (is.na(sem_archivo)) sem_archivo <- 1L
  profesor <- "Sin especificar"
  f_pr <- which(apply(nm[seq_len(min(25, nrow(nm))), , drop = FALSE], 1, function(r) any(grepl("^PROFES+OR(A)?$|^DOCENTE$", r))))
  if (length(f_pr) > 0) {
    r_p <- f_pr[1]
    c_p <- which(grepl("^PROFES+OR(A)?$|^DOCENTE$", nm[r_p, ]))[1]
    for (rr in seq(r_p + 1, min(nrow(m), r_p + 18))) {
      cand <- trimws(m[rr, c_p])
      if (nzchar(cand) && nchar(cand) > 4 && !grepl("^(ASIGNATURA|CURSO|ALUMNOS|NOTA)", norm_txt(cand))) {
        profesor <- limpiar_nombre_persona(cand)
        break
      }
    }
  }
  asig_interna <- ""
  f_as <- which(apply(nm[seq_len(min(25, nrow(nm))), , drop = FALSE], 1, function(r) any(r == "ASIGNATURA")))
  if (length(f_as) > 0) {
    r_a <- f_as[1]
    for (rr in seq(r_a + 1, min(nrow(m), r_a + 16))) {
      fila_vals <- m[rr, ]
      fila_vals <- fila_vals[nzchar(fila_vals)]
      for (v in fila_vals) {
        v_norm <- norm_txt(v)
        if (!grepl("^(2-A|1-A|4-A|5-A|8-A|[1-8]°|PROFESOR|CURSO|RESUMEN|YERBAS)", v_norm) &&
            v != RawToChar_safe(profesor) && !grepl(",", v, fixed = TRUE) || grepl("GEOGRAFIA|HISTORIA|LIMITES", v_norm)) {
          if (rr %in% c(r_a + 2, r_a + 14) && nchar(v) >= 4 && v_norm != norm_txt(profesor)) {
            asig_interna <- v
            break
          }
        }
      }
      if (nzchar(asig_interna)) break
    }
  }
  asignatura <- extraer_asignatura(nombre_archivo)
  if ((asignatura == "General" || !nzchar(asignatura)) && nzchar(asig_interna)) {
    asignatura <- aplicar_alias(asig_interna)
  }
  info <- parsear_curso(nombre_archivo)
  enc <- detectar_encabezado(nm)
  if (is.null(enc) || is.na(enc$col)) stop("no encontré la columna 'Alumnos' en la planilla")
  fila_h <- enc$fila
  c_nom <- enc$col
  if (fila_h >= nrow(m)) stop("no hay filas bajo el encabezado")
  c_curso_tabla <- which(nm[fila_h, ] == "CURSO")[1]
  if (is.null(info) && !is.na(c_curso_tabla)) {
    vals_c <- m[(fila_h + 1):nrow(m), c_curso_tabla]
    vals_c <- vals_c[nzchar(vals_c)]
    if (length(vals_c) > 0) info <- parsear_curso(vals_c[1])
  }
  if (is.null(info)) stop("no pude identificar el curso en el archivo")
  filas_posibles <- (fila_h + 1):nrow(m)
  filas <- filas_posibles[es_nombre_alumno(m[filas_posibles, c_nom])]
  if (length(filas) == 0) stop("no hay alumnos listados bajo el encabezado")
  nombres_limpios <- limpiar_nombre_persona(m[filas, c_nom])
  dup_mask <- !duplicated(norm_nombre(nombres_limpios))
  filas <- filas[dup_mask]
  nombres <- nombres_limpios[dup_mask]
  rows_h <- seq(max(1, fila_h - 2), min(nrow(nm), fila_h + 1))
  excluir <- function(j) {
    any(grepl("(ASIST|%|PORC|EDAD|FECHA|OBSERV|^RUT$|^RUN$|^CURSO$|^N$|^Nº$)", nm[rows_h, j]))
  }
  es_prom <- function(j) {
    any(grepl("^(NOTA|PROM|PROMEDIO|PROMEDIO FINAL|NOTA FINAL|FINAL|NF)$",
              nm[c(fila_h, min(nrow(nm), fila_h + 1)), j]))
  }
  cols_validas <- which(vapply(seq_len(ncol(m)), function(j) {
    j > c_nom && !excluir(j) && any(!is.na(num_nota(m[filas, j])))
  }, logical(1)))
  if (length(cols_validas) == 0) {
    diag <- sprintf("Año %d (S%d) | Prof: %s | %d alumnos listados, aún sin notas ingresadas.",
                    anio_archivo, sem_archivo, profesor, length(nombres))
    return(list(info = info, asignatura = asignatura, sem_archivo = sem_archivo,
                anio = anio_archivo, profesor = profesor,
                det = det_cols_vacio(), prom = prom_cols_vacio(),
                nombres = unique(nombres), diag = diag))
  }
  sem_lab <- rep(NA_integer_, ncol(m))
  for (r in seq(max(1, fila_h - 4), fila_h)) {
    for (j in seq_len(ncol(m))) {
      if (grepl("SEM|\\b1A\\b|\\b2A\\b", nm[r, j])) {
        s <- detectar_semestre(nm[r, j])
        if (!is.na(s)) sem_lab[j] <- s
      }
    }
  }
  asignar_sem <- function(j) {
    cand <- which(!is.na(sem_lab) & seq_along(sem_lab) <= j)
    if (length(cand) > 0) sem_lab[max(cand)] else sem_archivo
  }
  c_prom <- cols_validas[vapply(cols_validas, es_prom, logical(1))]
  if (length(c_prom) > 2) c_prom <- integer(0)
  cols_eval <- setdiff(cols_validas, c_prom)
  if (length(cols_eval) == 0 && length(c_prom) > 0) {
    cols_eval <- c_prom
    c_prom <- integer(0)
  }
  clasificar_tipo_eval <- function(nom_eval, sup_eval) {
    txt <- norm_txt(paste(nom_eval, sup_eval))
    if (grepl("APTUS|ENSAYO|SIMCE|DIA|PDD", txt)) return("Aptus / Ensayo")
    if (grepl("TEST|QUIZ|PRUEBA|CONTROL|UNIT|EXAM", norm_txt(nom_eval))) return("Prueba / Test")
    if (grepl("ORAL|EXPO|VIDEO|DISERTAC|PRESENTAC", norm_txt(nom_eval))) return("Exposición / Oral")
    if (grepl("CARPETA|INFORME|TRABAJO|FICHA|GUIA|TAREA|ACUMUL|TALLER", norm_txt(nom_eval))) return("Trabajo / Proceso")
    if (grepl("EXAMEN", norm_txt(sup_eval))) return("Evaluación Sumativa")
    "Parcial"
  }
  det <- det_cols_vacio()
  if (length(cols_eval) > 0) {
    sems <- vapply(cols_eval, asignar_sem, integer(1))
    idx <- ave(seq_along(cols_eval), sems, FUN = seq_along)
    nombres_eval <- vapply(seq_along(cols_eval), function(k) {
      j <- cols_eval[k]
      h_txt <- trimws(m[fila_h, j])
      if (!nzchar(h_txt) && fila_h > 1) h_txt <- trimws(m[fila_h - 1, j])
      if (!nzchar(h_txt) || grepl("^[0-9]+$", h_txt)) {
        paste0("Nota ", idx[k])
      } else {
        h_txt
      }
    }, character(1))
    
    tipos_eval <- vapply(seq_along(cols_eval), function(k) {
      j <- cols_eval[k]
      sup_txt <- if (fila_h > 2) paste(m[max(1, fila_h - 2):(fila_h - 1), j], collapse = " ") else ""
      clasificar_tipo_eval(nombres_eval[k], sup_txt)
    }, character(1))
    
    sub_eval <- matrix(num_nota(m[filas, cols_eval]), nrow = length(filas), ncol = length(cols_eval))
    idx_v <- which(!is.na(sub_eval), arr.ind = TRUE)
    if (nrow(idx_v) > 0) {
      det <- data.frame(
        Nombre_Notas      = nombres[idx_v[, 1]],
        Anio              = as.integer(anio_archivo),
        Semestre          = as.integer(sems[idx_v[, 2]]),
        Profesor          = profesor,
        Evaluacion        = as.integer(idx[idx_v[, 2]]),
        Evaluacion_Nombre = nombres_eval[idx_v[, 2]],
        Tipo_Eval         = tipos_eval[idx_v[, 2]],
        Nota              = sub_eval[idx_v],
        stringsAsFactors  = FALSE
      )
      det$Etiqueta <- paste0("S", det$Semestre, " · ", det$Evaluacion_Nombre)
      det$Asignatura <- asignatura
    }
  }
  prom <- prom_cols_vacio()
  if (length(c_prom) > 0) {
    sub_pr <- matrix(num_nota(m[filas, c_prom]), nrow = length(filas), ncol = length(c_prom))
    idx_p <- which(!is.na(sub_pr), arr.ind = TRUE)
    if (nrow(idx_p) > 0) {
      prom <- data.frame(
        Nombre_Notas = nombres[idx_p[, 1]],
        Anio         = as.integer(anio_archivo),
        Semestre     = as.integer(vapply(c_prom[idx_p[, 2]], asignar_sem, integer(1))),
        Profesor     = profesor,
        Promedio     = sub_pr[idx_p],
        Asignatura   = asignatura,
        stringsAsFactors = FALSE
      )
    }
  }
  if (nrow(prom) == 0 && nrow(det) > 0) {
    prom <- det %>%
      group_by(Nombre_Notas, Anio, Semestre, Profesor, Asignatura) %>%
      summarise(Promedio = round(mean(Nota), 1), .groups = "drop") %>%
      as.data.frame()
  }
  if (
    nrow(det) > 0) {
    prom_calc <- det %>%
      group_by(Nombre_Notas, Anio, Semestre, Profesor, Asignatura) %>%
      summarise(Prom_Calc = round(mean(Nota), 1), .groups = "drop")
    if (nrow(prom) > 0) {
      prom <- full_join(prom, prom_calc, by = c("Nombre_Notas", "Anio", "Semestre", "Profesor", "Asignatura")) %>%
        mutate(Promedio = ifelse(is.na(Promedio), Prom_Calc, Promedio)) %>%
        select(-Prom_Calc) %>%
        as.data.frame()
    } else {
      prom <- prom_calc %>% rename(Promedio = Prom_Calc) %>% as.data.frame()
    }
  }
  eval_nombres_resumen <- if (length(cols_eval) > 0) paste(unique(det$Evaluacion_Nombre), collapse = ", ") else "sin evaluaciones"
  list(info = info, asignatura = asignatura, sem_archivo = sem_archivo,
       anio = anio_archivo, profesor = profesor,
       det = det, prom = prom, nombres = unique(nombres),
       diag = sprintf("Año %d (S%d) | Prof: %s | %d alumnos (%d con notas) | %d evals (%s).",
                      anio_archivo, sem_archivo, profesor, length(unique(nombres)),
                      length(unique(prom$Nombre_Notas)), length(cols_eval), eval_nombres_resumen))
}
