# LECTURA DE DIAGNÓSTICO DIA
# Lee los Excel DIA de la Agencia de Calidad: detecta año y etapa (inicio, intermedio, final) y el logro por eje.
# ==============================================================================
dia_res_vacio <- data.frame(
