# Lee un Excel DIA (logro por alumno y por eje temático). El curso sale de la celda Curso o del nombre del archivo (número normal = básico; número romano I, II, III, IV = medio; luego la letra y, si existe, un código entre paréntesis que se ignora); el año, del nombre o de la fecha.
leer_dia_archivo <- function(ruta, nombre_archivo) {
  nn <- norm_txt(nombre_archivo)
  if (grepl("INGLES", nn)) stop("Asignatura Inglés ignorada en módulo DIA por configuración.")
  raw <- suppressMessages(read_excel(ruta, sheet = 1, col_names = FALSE,
                                     col_types = "text", .name_repair = "minimal"))
  m <- as.matrix(raw)
  m[is.na(m)] <- ""
  m[] <- trimws(m)
  nm <- norm_txt(m)
  curso_celda <- ""
  fecha_celda <- ""
  for (r in seq_len(min(10, nrow(m)))) {
    if (grepl("^CURSO$", nm[r, 1])) curso_celda <- m[r, 2]
    if (grepl("FECHA", nm[r, 1]))   fecha_celda <- m[r, 2]
  }
  info_c <- parsear_curso(if (nzchar(curso_celda)) curso_celda else nombre_archivo)
  m_curso_arch <- regmatches(nn, regexec("_(IV|III|II|I|[0-9]{1,2})_([A-Z])(?: *\\([^)]*\\))?_(?:INICIO|CIERRE|MONITOREO|INTERMEDI|FINAL|DIAGNOSTIC)",
                                         nn, perl = TRUE))[[1]]
  if (length(m_curso_arch) >= 3 && !grepl("BASIC|MEDI", norm_txt(curso_celda))) {
    cod_c <- m_curso_arch[2]
    es_rom <- cod_c %in% c("I", "II", "III", "IV")
    info_c <- list(num = if (es_rom) c(I = 1L, II = 2L, III = 3L, IV = 4L)[[cod_c]] else as.integer(cod_c),
                   tipo = if (es_rom) "M" else "B",
                   letra = m_curso_arch[3])
  }
  if (is.null(info_c)) {
    cel_n <- norm_txt(curso_celda)
    m_rom <- regmatches(cel_n, regexec("^\\s*(IV|III|II|I)[^A-Z]*(?:MEDIO)?[^A-Z]*([A-Z])?\\s*$", cel_n, perl = TRUE))[[1]]
    if (length(m_rom) >= 2) {
      info_c <- list(num = c(I = 1L, II = 2L, III = 3L, IV = 4L)[[m_rom[2]]], tipo = "M",
                     letra = if (length(m_rom) >= 3) m_rom[3] else "")
    }
  }
  if (is.null(info_c)) stop("No se pudo identificar el curso en el archivo DIA.")
  curso_fmt <- etiqueta_curso(info_c)
  anio <- NA_integer_
  m_a <- regmatches(nn, regexec("(?<![0-9])(202[4-9])(?![0-9])", nn, perl = TRUE))[[1]]
  if (length(m_a) >= 2) {
    anio <- as.integer(m_a[2])
  } else {
    m_y_in <- regmatches(fecha_celda, regexec("\\b(202[4-9])\\b", fecha_celda))[[1]]
    if (length(m_y_in) >= 2) anio <- as.integer(m_y_in[2]) else anio <- as.integer(format(Sys.Date(), "%Y"))
  }
  
  if (grepl("INICIO|DIAGNOSTIC", nn)) {
    etapa <- "Inicio"
    mes_num <- "03"
  } else if (grepl("CIERRE|FINAL", nn)) {
    etapa <- "Final"
    mes_num <- "11"
  } else if (grepl("MONITOREO|INTERMEDI", nn)) {
    etapa <- "Intermedio"
    mes_num <- "09"
  } else {
    m_dmy <- regmatches(fecha_celda, regexec("([0-9]{1,2})[-/]([0-9]{1,2})[-/]([0-9]{4})", fecha_celda))[[1]]
    m_val <- if (length(m_dmy) == 4) as.integer(m_dmy[3]) else 9L
    if (m_val <= 5) { etapa <- "Inicio"; mes_num <- "03" }
    else if (m_val >= 10) { etapa <- "Final"; mes_num <- "11" }
    else { etapa <- "Intermedio"; mes_num <- "09" }
  }
  
  anio_mes <- sprintf("%04d-%s", anio, mes_num)
  nombre_mes <- if (!is.na(mes_num) && mes_num %in% names(meses_es)) meses_es[mes_num] else "Mes"
  etiqueta_fecha <- sprintf("%s (%s %s %d)", anio_mes, etapa, nombre_mes, anio)
  fila_h <- which(apply(nm, 1, function(r) {
    any(grepl("^NOMBRE DEL ESTUDIANTE", r) | r == "NOMBRE") & sum(nzchar(r)) >= 3
  }))[1]
  if (is.na(fila_h)) stop("No se encontró la cabecera con 'Nombre del Estudiante'.")
  c_lista <- which(grepl("LISTA|^N$|^N°$", nm[fila_h, ]))[1]
  c_nom   <- which(grepl("^NOMBRE DEL ESTUDIANTE", nm[fila_h, ]) | nm[fila_h, ] == "NOMBRE")[1]
  c_niv   <- which(grepl("NIVEL DE LOGRO", nm[fila_h, ]))[1]
  col_fin <- if (!is.na(c_niv)) (c_niv - 1) else ncol(m)
  cols_ejes <- setdiff(seq(c_nom + 1, col_fin), c(c_lista, c_nom, if (!is.na(c_niv)) c_niv else integer(0)))
  cols_ejes <- cols_ejes[nzchar(m[fila_h, cols_ejes])]
  if (length(cols_ejes) == 0) stop("No se encontraron columnas de ejes temáticos u Objetivos de Aprendizaje (OA).")
  nombres_ejes <- m[fila_h, cols_ejes]
  ejes_txt <- paste(norm_txt(nombres_ejes), collapse = " ")
  asignatura <- if (grepl("LECTURA|LENGUA", nn) || grepl("LOCALIZAR|REFLEXIONAR", ejes_txt)) {
    "Lectura"
  } else if (grepl("MATEMAT", nn) || grepl("GEOMETRIA|ALGEBRA|^OA", ejes_txt)) {
    "Matemática"
  } else if (grepl("HISTORIA|GEOGRAFIA|SOCIALES", nn) || grepl("CIUDADANA", ejes_txt)) {
    "Historia"
  } else if (grepl("CIENCIAS|NATURALES", nn) || grepl("BIOLOGIA|FISICA|QUIMICA|TIERRA", ejes_txt)) {
    "Ciencias Naturales"
  } else "Otra"
  filas <- (fila_h + 1):nrow(m)
  filas <- filas[es_nombre_alumno(m[filas, c_nom])]
  if (length(filas) == 0) stop("No se encontraron estudiantes en la planilla DIA.")
  nombres_est <- limpiar_nombre_persona(m[filas, c_nom])
  n_lista_val <- if (!is.na(c_lista)) suppressWarnings(as.integer(as.numeric(m[filas, c_lista]))) else seq_along(filas)
  mat_ejes <- sapply(cols_ejes, function(cj) {
    suppressWarnings(as.numeric(gsub(",", ".", gsub("%", "", m[filas, cj]))))
  })
  if (length(filas) == 1) mat_ejes <- matrix(mat_ejes, nrow = 1)
  colnames(mat_ejes) <- nombres_ejes
  prom_logro <- round(rowMeans(mat_ejes, na.rm = TRUE), 1)
  prom_logro[is.nan(prom_logro)] <- NA_real_
  if (!is.na(c_niv)) {
    niv_raw <- norm_txt(m[filas, c_niv])
    niv_std <- case_when(
      grepl("\\bIII\\b|3", niv_raw) ~ "Nivel III (Satisfactorio)",
      grepl("\\bII\\b|2", niv_raw)  ~ "Nivel II (Parcial)",
      grepl("\\bI\\b|1", niv_raw)   ~ "Nivel I (No logrado)",
      TRUE ~ NA_character_
    )
  } else {
    niv_std <- case_when(
      prom_logro >= 75 ~ "Nivel III (Satisfactorio)",
      prom_logro >= 40 ~ "Nivel II (Parcial)",
      TRUE ~ "Nivel I (No logrado)"
    )
  }
  eje_debil  <- apply(mat_ejes, 1, function(v) if (all(is.na(v))) "-" else nombres_ejes[which.min(v)][1])
  logro_min  <- apply(mat_ejes, 1, function(v) if (all(is.na(v))) NA_real_ else round(min(v, na.rm = TRUE), 1))
  eje_fuerte <- apply(mat_ejes, 1, function(v) if (all(is.na(v))) "-" else nombres_ejes[which.max(v)][1])
  logro_max  <- apply(mat_ejes, 1, function(v) if (all(is.na(v))) NA_real_ else round(max(v, na.rm = TRUE), 1))
  res_alumnos <- data.frame(
    Archivo = nombre_archivo, Curso = curso_fmt, Asignatura = asignatura,
    Etapa = etapa, Anio = anio, Mes_Num = mes_num, Anio_Mes = anio_mes,
    Etiqueta_Fecha = etiqueta_fecha, N_Lista = n_lista_val, Alumno = nombres_est,
    Promedio_Logro = prom_logro, Eje_Debil = eje_debil, Logro_Min = logro_min,
    Eje_Fuerte = eje_fuerte, Logro_Max = logro_max,
    Brecha_Ejes = round(logro_max - logro_min, 1),
    Nivel_DIA = niv_std, stringsAsFactors = FALSE
  ) %>%
    filter(!is.na(Promedio_Logro) | !is.na(Nivel_DIA)) %>%
    filter(!(Promedio_Logro == 0 & Logro_Max == 0 & Logro_Min == 0))
  ejes_long <- bind_rows(lapply(seq_along(nombres_ejes), function(k) {
    data.frame(
      Archivo = nombre_archivo, Curso = curso_fmt, Asignatura = asignatura,
      Etapa = etapa, Anio = anio,  Anio_Mes = anio_mes, Etiqueta_Fecha = etiqueta_fecha,
      Alumno = nombres_est, Eje = nombres_ejes[k], Logro = mat_ejes[, k],
      Nivel_DIA = niv_std, stringsAsFactors = FALSE
    )
  })) %>% filter(!is.na(Logro))
  list(res = res_alumnos, ejes = ejes_long, curso = curso_fmt, asignatura = asignatura,
       periodo = paste(etapa, anio_mes), n_alumnos = nrow(res_alumnos), n_ejes = length(nombres_ejes))
}
# ==============================================================================
# ENTRADAS DE ARCHIVOS
# Procesa cada archivo cargado una sola vez y guarda su resultado o su error, sin detener la app.
# ==============================================================================
# Crea el registro de estado de un archivo cargado.
nueva_entrada <- function(nombre, tipo, ok, estado, detalle, curso_txt = "-",
                          asignatura = "-", semestre = "-", anio = "-",
                          profesor = "-", n_alumnos = NA_integer_,
                          n_notas = NA_integer_, res = NULL) {
  list(nombre = nombre, tipo = tipo, ok = ok, estado = estado, detalle = detalle,
       curso_txt = curso_txt, asignatura = asignatura, semestre = semestre,
       anio = as.character(anio), profesor = profesor,
       n_alumnos = n_alumnos, n_notas = n_notas, res = res)
}
# Procesa un archivo de asistencia y devuelve su registro (OK o error).
procesar_asistencia <- function(ruta, nombre) {
  r <- tryCatch(leer_asistencia_archivo(ruta, nombre), error = function(e) e)
  if (inherits(r, "error")) {
    return(nueva_entrada(nombre, "Asistencia", FALSE, "Error", conditionMessage(r)))
  }
  nueva_entrada(
    nombre, "Asistencia", TRUE, "OK",
    sprintf("%d meses leídos, %d registros.", length(unique(r$Mes)), nrow(r)),
    curso_txt = etiqueta_curso_segura(unique(r$Curso)[1]),
    n_alumnos = length(unique(r$Nombre)), res = r
  )
}
# Procesa un archivo de notas y devuelve su registro (OK, sin notas o error).
procesar_notas <- function(ruta, nombre) {
  r <- tryCatch(leer_notas_archivo(ruta, nombre), error = function(e) e)
  if (inherits(r, "error")) {
    return(nueva_entrada(nombre, "Notas", FALSE, "Error", conditionMessage(r)))
  }
  sin_notas <- nrow(r$det) == 0 && nrow(r$prom) == 0
  sems <- sort(unique(c(r$det$Semestre, r$prom$Semestre)))
  if (length(sems) == 0) sems <- r$sem_archivo
  nueva_entrada(
    nombre, "Notas", TRUE, if (sin_notas) "Sin notas aún" else "OK", r$diag,
    curso_txt = etiqueta_curso(r$info), asignatura = r$asignatura,
    semestre = paste(sems, collapse = ", "), anio = r$anio, profesor = r$profesor,
    n_alumnos = length(r$nombres), n_notas = nrow(r$det), res = r
  )
}
# Procesa un archivo PDD y devuelve su registro (OK o error).
procesar_pdd <- function(ruta, nombre) {
  r <- tryCatch(leer_pdd_archivo(ruta, nombre), error = function(e) e)
  if (inherits(r, "error")) {
    return(nueva_entrada(nombre, "PDD (Diagnóstico)", FALSE, "Error", conditionMessage(r)))
  }
  nueva_entrada(
    nombre, "PDD (Diagnóstico)", TRUE, "OK",
    sprintf("%d evaluados (logro medio %.1f%%).", nrow(r), mean(r$Logro, na.rm = TRUE)),
    curso_txt = paste(unique(r$Curso), collapse = ", "),
    asignatura = paste(unique(r$Asignatura), collapse = ", "),
    n_alumnos = length(unique(r$RUT)), n_notas = nrow(r), res = r
  )
}
# Procesa un archivo DIA y devuelve su registro (OK o error).
procesar_dia <- function(ruta, nombre) {
  r <- tryCatch(leer_dia_archivo(ruta, nombre), error = function(e) e)
  if (inherits(r, "error")) {
    return(nueva_entrada(nombre, "DIA (Agencia)", FALSE, "Error", conditionMessage(r)))
  }
  nueva_entrada(
    nombre, "DIA (Agencia)", TRUE, "OK",
    sprintf("%s | %d alumnos, %d ejes (logro medio %.1f%%).",
            r$periodo, r$n_alumnos, r$n_ejes, mean(r$res$Promedio_Logro, na.rm = TRUE)),
    curso_txt = r$curso, asignatura = r$asignatura, semestre = r$periodo,
    anio = if (nrow(r$res) > 0) r$res$Anio[1] else "-",
    n_alumnos = r$n_alumnos, n_notas = nrow(r$ejes), res = r
  )
}
