# Calcula el promedio general y las asignaturas en rojo de cada alumno.
pg_alumno <- function(df) {
  if (nrow(df) == 0) {
    return(data.frame(Curso = character(), Alumno = character(), Anios_Txt = character(),
                      Semestres_Txt = character(), PG = numeric(),
                      N_Asig = integer(), N_Rojas = integer(), stringsAsFactors = FALSE))
  }
  df %>%
    filter(es_nombre_alumno(Alumno)) %>%
    group_by(Curso, Alumno) %>%
    summarise(
      Anios_Txt = if ("Anio" %in% names(df)) paste(sort(unique(na.omit(Anio))), collapse = " / ") else "-",
      Semestres_Txt = if ("Semestre" %in% names(df)) paste0("S", sort(unique(na.omit(Semestre))), collapse = ", ") else "-",
      PG = round(mean(Promedio), 1),
      N_Asig = n_distinct(Asignatura),
      N_Rojas = sum(Promedio < NOTA_ROJA),
      .groups = "drop"
    )
}

# Igual que pg_alumno, pero separado por año y semestre.
pg_alumno_epoca <- function(df) {
  if (nrow(df) == 0) return(data.frame())
  df %>%
    filter(es_nombre_alumno(Alumno)) %>%
    mutate(Epoca = sprintf("%s · S%s", ifelse(is.na(Anio), "S/A", Anio), ifelse(is.na(Semestre), "1", Semestre))) %>%
    group_by(Alumno, Curso, Anio, Semestre, Epoca) %>%
    summarise(
      PG = round(mean(Promedio, na.rm = TRUE), 1),
      N_Asig = n_distinct(Asignatura),
      N_Rojas = sum(Promedio < NOTA_ROJA, na.rm = TRUE),
      .groups = "drop"
    )
}
