})
prom_base <- reactive({
  nd <- notas_data()
  if (nrow(nd$det) == 0 && nrow(nd$prom) == 0) return(prom_vacio)
  calc <- nd$det %>%
    filter(!is.na(Alumno)) %>%
    group_by(Curso, Asignatura, Alumno, Anio, Semestre, Profesor) %>%
    summarise(Prom_calc = round(mean(Nota), 1), .groups = "drop")
  
  p <- nd$prom %>%
    filter(!is.na(Alumno)) %>%
    select(Curso, Asignatura, Alumno, Anio, Semestre, Profesor, Promedio)
  
  if (nrow(calc) > 0) {
    p <- full_join(p, calc, by = c("Curso", "Asignatura", "Alumno", "Anio", "Semestre", "Profesor")) %>%
      mutate(Promedio = ifelse(is.na(Promedio), Prom_calc, Promedio))
  }
  p <- p %>% filter(!is.na(Promedio))
  p <- filtra_anio(filtra_sem(filtra_prof(p)))
  if (nrow(p) == 0) return(prom_vacio)
  
  p %>%
    group_by(Curso, Asignatura, Alumno, Anio, Semestre) %>%
    summarise(Promedio = round(mean(Promedio), 1),
              Profesor = paste(unique(Profesor), collapse = " / "),
              .groups = "drop")
})

