catalogo_cursos <- reactive({
  unique(c(names(todos_los_cursos()), notas_data()$vinc$Curso))
})

nombres_referencia <- reactive({
  a <- if (asist_cargada()) {
    datos_globales() %>% distinct(Curso, Alumno = Nombre)
  } else data.frame(Curso = character(), Alumno = character(), stringsAsFactors = FALSE)
  v <- notas_data()$vinc
  n <- if (nrow(v) > 0) {
    v %>% distinct(Curso, Alumno)
  } else data.frame(Curso = character(), Alumno = character(), stringsAsFactors = FALSE)
  bind_rows(a, n) %>% distinct()
})

pdd_data <- reactive({
  entradas <- Filter(function(e) isTRUE(e$ok), pdd_parseada())
  if (length(entradas) == 0) return(pdd_vacio)
  d <- bind_rows(lapply(entradas, function(e) e$res))
  
  catalogo <- catalogo_cursos()
  cursos_u <- unique(d$Curso)
  map_c <- vapply(cursos_u, function(cu) {
    ca <- emparejar_curso(parsear_curso(cu), catalogo)
    if (is.na(ca)) cu else ca
  }, character(1))
  d$Curso_Canon <- unname(map_c[d$Curso])
  
  ref_all <- nombres_referencia()
  d$Alumno_Canon <- d$Alumno
  d$Vinculado <- FALSE
  for (cc in unique(d$Curso_Canon)) {
    ref <- unique(ref_all$Alumno[ref_all$Curso == cc])
    if (length(ref) == 0) next
    idx <- which(d$Curso_Canon == cc)
    nom_pdd <- unique(d$Alumno[idx])
    mp <- emparejar_uno_a_uno(ref, nom_pdd)
    rep_n <- unname(mp[d$Alumno[idx]])
    ok <- !is.na(rep_n)
    d$Alumno_Canon[idx[ok]] <- rep_n[ok]
    d$Vinculado[idx[ok]] <- TRUE
  }
  d
  
})

pdd_cargado <- reactive(nrow(pdd_data()) > 0)

# DIA consolidado

dia_data <- reactive({
  entradas <- Filter(function(e) isTRUE(e$ok), dia_parseada())
  if (length(entradas) == 0) return(list(res = dia_res_vacio, ejes = dia_ejes_vacio))
  
  res_df  <- bind_rows(lapply(entradas, function(e) e$res$res))
  ejes_df <- bind_rows(lapply(entradas, function(e) e$res$ejes))
  
  catalogo <- catalogo_cursos()
  cursos_u <- unique(res_df$Curso)
  map_c <- vapply(cursos_u, function(cu) {
    ca <- emparejar_curso(parsear_curso(cu), catalogo)
    if (is.na(ca)) cu else ca
  }, character(1))
  res_df$Curso_Canon  <- unname(map_c[res_df$Curso])
  ejes_df$Curso_Canon <- unname(map_c[ejes_df$Curso])
  
  ref_all <- nombres_referencia()
  if (pdd_cargado()) {
    ref_all <- bind_rows(ref_all, pdd_data() %>% distinct(Curso = Curso_Canon, Alumno = Alumno_Canon)) %>% distinct()
  }
  res_df$Alumno_Canon  <- res_df$Alumno
  res_df$Vinculado     <- FALSE
  ejes_df$Alumno_Canon <- ejes_df$Alumno
  
  for (cc in unique(res_df$Curso_Canon)) {
    ref <- unique(ref_all$Alumno[ref_all$Curso == cc])
    if (length(ref) == 0) next
    idx_r <- which(res_df$Curso_Canon == cc)
    mp <- emparejar_uno_a_uno(ref, unique(res_df$Alumno[idx_r]))
    rep_r <- unname(mp[res_df$Alumno[idx_r]])
    ok_r <- !is.na(rep_r)
    res_df$Alumno_Canon[idx_r[ok_r]] <- rep_r[ok_r]
    res_df$Vinculado[idx_r[ok_r]]    <- TRUE
    
    idx_e <- which(ejes_df$Curso_Canon == cc)
    rep_e <- unname(mp[ejes_df$Alumno[idx_e]])
    ok_e <- !is.na(rep_e)
    ejes_df$Alumno_Canon[idx_e[ok_e]] <- rep_e[ok_e]
  }
  
  list(res = res_df, ejes = ejes_df)
  
})

dia_cargado <- reactive(nrow(dia_data()$res) > 0)

