# Alumnos que cuenta el KPI: manda la lista de asistencia; lo no vinculado se informa aparte.
alumnos_roster <- reactive({
  req(input$select_curso)
  vacio <- data.frame(Curso = character(), Alumno = character(), Fuente = character(), stringsAsFactors = FALSE)
  a <- if (asist_cargada()) datos_globales() %>% distinct(Curso, Alumno = Nombre) %>% mutate(Fuente = "A") else vacio
  v <- notas_data()$vinc
  n <- if (nrow(v) > 0) v %>% distinct(Curso, Alumno) %>% mutate(Fuente = "O") else vacio
  p <- if (pdd_cargado()) pdd_data() %>% distinct(Curso = Curso_Canon, Alumno = Alumno_Canon) %>% mutate(Fuente = "O") else vacio
  d <- if (dia_cargado()) dia_data()$res %>% distinct(Curso = Curso_Canon, Alumno = Alumno_Canon) %>% mutate(Fuente = "O") else vacio
  todo <- bind_rows(a, n, p, d) %>% filter(es_nombre_alumno(Alumno))
  if (input$select_curso != "TODOS") todo <- todo %>% filter(Curso == input$select_curso)
  con_asist <- names(todos_los_cursos())
  base <- todo %>% filter(Fuente == "A" | !(Curso %in% con_asist)) %>% distinct(Curso, Alumno)
  extra <- todo %>% distinct(Curso, Alumno) %>% anti_join(base, by = c("Curso", "Alumno"))
  list(n = nrow(base), extra = nrow(extra))
})
output$kpi_alumnos <- renderUI({
  r <- alumnos_roster()
  tagList(
