# Estudiantes bajo 85%: gráfico por curso; con clic abre la lista de alumnos
criticos_data <- reactive({
  d <- datos_globales()
  if (nrow(d) == 0) return(NULL)
  
  criticos <- d %>%
    group_by(Curso, Nombre) %>%
    summarise(Pct = mean(Estado == "Asistió") * 100, .groups = "drop") %>%
    filter(Pct < UMBRAL_ASIST) %>%
    group_by(Curso) %>%
    summarise(Cant = n(), .groups = "drop")
  
  criticos <- left_join(data.frame(Curso = unique(d$Curso)), criticos, by = "Curso") %>%
    mutate(Cant = ifelse(is.na(Cant), 0, Cant))
  criticos$Etiqueta <- etiquetar(criticos$Curso)
  
  criticos <- criticos %>% arrange(Cant, Etiqueta)
  criticos$Etiqueta <- factor(criticos$Etiqueta, levels = criticos$Etiqueta)
  criticos
})

