observeEvent(input$click_asist_categorias, {
  clk <- input$click_asist_categorias
  req(clk, asist_cargada())
  res <- asist_cat_data()
  req(!is.null(res))
  
  idx_y <- round(clk$y)
  if (is.na(idx_y) || idx_y < 1 || idx_y > length(res$niveles)) return()
  
  curso_sel <- res$niveles[idx_y]
  curso_orig <- res$d$Curso[as.character(res$d$Etiqueta) == curso_sel][1]
  
  sub_d <- res$d %>% filter(as.character(Etiqueta) == curso_sel)
  tot <- sum(sub_d$n)
  if (tot == 0) return()
  
  n_crit   <- sum(sub_d$n[sub_d$Categoria == "Critica (<85%)"])
  n_riesgo <- sum(sub_d$n[sub_d$Categoria == "En riesgo (85-89%)"])
  n_norm   <- sum(sub_d$n[sub_d$Categoria == "Normal (90-94%)"])
  
  lim1 <- n_crit / tot
  lim2 <- (n_crit + n_riesgo) / tot
  lim3 <- (n_crit + n_riesgo + n_norm) / tot
  
  cat_detectada <- if (clk$x <= lim1) {
    "Critica (<85%)"
  } else if (clk$x <= lim2) {
    "En riesgo (85-89%)"
  } else if (clk$x <= lim3) {
    "Normal (90-94%)"
  } else {
    "Destacada (>=95%)"
  }
  
  ar_curso <- asist_resumen() %>% filter(Curso == curso_orig)
  datos_modal_asist_categorias(list(curso = curso_sel, df = ar_curso))
  
  showModal(modalDialog(
    title = paste("Categorías de asistencia —", curso_sel),
    div(
      class = "mb-3",
      selectInput("modal_select_cat_asist", "Filtrar por categoría de asistencia:",
                  choices = c(
                    "Todos los estudiantes del curso" = "TODAS",
                    "Crítica (<85%)" = "Critica (<85%)",
                    "En riesgo (85-89%)" = "En riesgo (85-89%)",
                    "Normal (90-94%)" = "Normal (90-94%)",
                    "Destacada (>=95%)" = "Destacada (>=95%)"
                  ),
                  selected = cat_detectada, width = "100%")
    ),
    div(class = "scroll-box", tableOutput("tabla_modal_asist_categorias")),
    easyClose = TRUE, size = "l", footer = modalButton("Cerrar")
  ))
})

