    group_by(Curso, Asignatura) %>%
    summarise(Prom = mean(Promedio, na.rm = TRUE), .groups = "drop")
  res$Etiqueta <- etiquetar(res$Curso)
  
  u_cursos <- unique(res$Curso)
  p_info   <- lapply(u_cursos, parsear_curso)
  tipo_val <- vapply(p_info, function(x) if (is.null(x)) 99L else if (x$tipo == "M") 2L else 1L, integer(1))
  num_val  <- vapply(p_info, function(x) if (is.null(x)) 99L else x$num, integer(1))
  let_val  <- vapply(p_info, function(x) if (is.null(x) || !nzchar(x$letra)) " " else x$letra, character(1))
  
  orden_cursos_u <- u_cursos[order(tipo_val, num_val, let_val, decreasing = FALSE)]
  res$Etiqueta <- factor(res$Etiqueta, levels = etiquetar(orden_cursos_u))
  
  colores_fijos <- c(
    "Lengua y Literatura"                     = "#2f6db5",
