    "Ciencias de la Salud"                    = "#14a3a0",
    "Ciencias para la Ciudadanía"             = "#14a3a0",
    "Física"                                  = "#14a3a0",
    "Química"                                 = "#14a3a0",
    "Idioma Extranjero: Inglés"               = "#8e6bbf",
    "Taller de Inglés"                        = "#8e6bbf",
    "Educación Física y Salud"                = "#10b981",
    "Filosofía"                               = "#c0508f",
    "Música"                                  = "#06b6d4",
    "Artes Visuales"                          = "#eab308",
    "Tecnología"                              = "#ea580c"
  )
  
  asigs_presentes <- unique(res$Asignatura)
