# Mapa de evaluaciones: resumen del colegio o detalle de un curso
output$plot_notas_global_heat <- renderPlot({
  validate(need(notas_cargadas(), "Sube planillas de notas primero."))
  d_det  <- det_filtrado()
  d_prom <- prom_filtrado()
  validate(need(nrow(d_det) > 0 || nrow(d_prom) > 0, "No hay notas disponibles para graficar."))
  
  modo <- if (is.null(input$heat_modo_vista)) "MACRO" else input$heat_modo_vista
  
  # Orden pedagógico de cursos (1° Básico a 4° Medio)
  ordenar_cursos_logico <- function(df_cursos) {
    u_c <- unique(df_cursos)
    p_info   <- lapply(u_c, parsear_curso)
    tipo_val <- vapply(p_info, function(x) if (is.null(x)) 99L else if (x$tipo == "M") 2L else 1L, integer(1))
    num_val  <- vapply(p_info, function(x) if (is.null(x)) 99L else x$num, integer(1))
    let_val  <- vapply(p_info, function(x) if (is.null(x) || !nzchar(x$letra)) " " else x$letra, character(1))
    u_c[order(tipo_val, num_val, let_val, decreasing = TRUE)]
  }
  
  # Modo 1: resumen del colegio (cursos vs asignaturas)
  if (modo == "MACRO") {
    h <- d_prom %>%
      group_by(Curso, Asignatura) %>%
      summarise(Prom = round(mean(Promedio, na.rm = TRUE), 1), .groups = "drop") %>%
      mutate(Curso_Etiq = etiquetar(Curso))
    
    cursos_ordenados <- etiquetar(ordenar_cursos_logico(unique(h$Curso)))
    h$Curso_Etiq <- factor(h$Curso_Etiq, levels = cursos_ordenados)
    
    ggplot(h, aes(x = Asignatura, y = Curso_Etiq, fill = Prom)) +
      geom_tile(color = "white", linewidth = 1) +
      geom_text(aes(label = sprintf("%.1f", Prom)), fontface = "bold", size = 3.8) +
      scale_fill_gradient2(
        low = col_rojo, mid = "#f8fafc", high = col_azul, midpoint = 5.0,
        limits = c(3.0, 7.0), oob = scales::squish, name = "Promedio"
      ) +
      labs(
        title = "Promedio general por Curso y Asignatura (Matriz Colegio)",
        subtitle = "Rojo = promedio en riesgo (< 4.0) | Azul = rendimiento adecuado/destacado (>= 5.0)",
        x = NULL, y = NULL
      ) +
      tema_dash(11) +
      theme(
        axis.text.x = element_text(face = "bold", angle = 20, hjust = 1, size = 9.5),
        axis.text.y = element_text(face = "bold", size = 9.5),
        panel.grid = element_blank(),
        legend.position = "right"
      )
    
    # Modo 2: detalle de evaluaciones de un curso
  } else {
    d_sub <- d_det
    if (!is.null(input$heat_sel_curso) && input$heat_sel_curso != "Sin cursos") {
      d_sub <- d_sub %>% filter(etiquetar(Curso) == input$heat_sel_curso)
    } else if (!is.null(input$select_curso) && input$select_curso != "TODOS") {
      d_sub <- d_sub %>% filter(Curso == input$select_curso)
    } else {
      primer_curso <- unique(d_sub$Curso)[1]
      d_sub <- d_sub %>% filter(Curso == primer_curso)
    }
    
    validate(need(nrow(d_sub) > 0, "Sin notas individuales para el curso seleccionado."))
    
    h <- d_sub %>%
      mutate(Eje_X = sprintf("S%d · Eval %d\n(%s)", Semestre, Evaluacion, substr(Evaluacion_Nombre, 1, 10))) %>%
      group_by(Asignatura, Semestre, Evaluacion, Eje_X) %>%
      summarise(Prom = round(mean(Nota, na.rm = TRUE), 1), .groups = "drop") %>%
      arrange(Semestre, Evaluacion)
    
    h$Eje_X <- factor(h$Eje_X, levels = unique(h$Eje_X))
    curso_nombre <- etiquetar(unique(d_sub$Curso)[1])
    
    ggplot(h, aes(x = Eje_X, y = reorder(Asignatura, Prom), fill = Prom)) +
      geom_tile(color = "white", linewidth = 1.2) +
      geom_text(aes(label = sprintf("%.1f", Prom)), fontface = "bold", size = 3.6) +
      scale_fill_gradient2(
        low = col_rojo, mid = "#f8fafc", high = col_azul, midpoint = 5.0,
        limits = c(3.0, 7.0), oob = scales::squish, name = "Nota"
      ) +
      labs(
        title = paste("Detalle de evaluaciones —", curso_nombre),
        subtitle = "Filas: Asignaturas del curso | Columnas: Pruebas y exámenes en orden cronológico",
        x = NULL, y = NULL
      ) +
      tema_dash(11) +
      theme(
        axis.text.x = element_text(face = "bold", angle = 15, hjust = 1, size = 9, lineheight = 0.95),
        axis.text.y = element_text(face = "bold", size = 9.5),
        panel.grid = element_blank(),
        legend.position = "right"
      )
  }
})

