  updateSelectInput(session, "aud_nombre_eval", selected = "Todas")
  updateSelectInput(session, "aud_desempeno", selected = "TODOS")
  updateTextInput(session, "aud_buscar_alumno", value = "")
  updateSelectInput(session, "aud_orden", selected = "ASC")
