auditoria_filtrada <- reactive({
  d <- notas_data()$det
  if (nrow(d) == 0) return(d)
  d$Curso_Etiqueta <- etiquetar(d$Curso)
  d$Desempeno <- clasificar_desempeno_nota(d$Nota)
  
  if (!is.null(input$aud_anio) && input$aud_anio != "Todos") {
    d <- d %>% filter(Anio == as.integer(input$aud_anio))
  }
  if (!is.null(input$aud_semestre) && input$aud_semestre != "Todos") {
    s <- suppressWarnings(as.integer(gsub("[^0-9]", "", input$aud_semestre)))
    if (!is.na(s)) d <- d %>% filter(Semestre == s)
  }
  if (!is.null(input$aud_curso) && input$aud_curso != "Todos") {
    d <- d %>% filter(Curso_Etiqueta == input$aud_curso)
  }
  if (!is.null(input$aud_asignatura) && input$aud_asignatura != "Todas") {
    d <- d %>% filter(Asignatura == input$aud_asignatura)
  }
  if (!is.null(input$aud_profesor) && input$aud_profesor != "Todos") {
    d <- d %>% filter(Profesor == input$aud_profesor)
  }
  if (!is.null(input$aud_tipo_eval) && input$aud_tipo_eval != "Todos") {
    d <- d %>% filter(Tipo_Eval == input$aud_tipo_eval)
  }
  if (!is.null(input$aud_nombre_eval) && input$aud_nombre_eval != "Todas") {
    d <- d %>% filter(Evaluacion_Nombre == input$aud_nombre_eval)
  }
  if (!is.null(input$aud_desempeno) && input$aud_desempeno != "TODOS") {
    if (input$aud_desempeno == "MAL_DESEMPENO") {
      d <- d %>% filter(Nota < 5.0)
    } else {
      d <- d %>% filter(Desempeno == input$aud_desempeno)
    }
  }
  if (!is.null(input$aud_buscar_alumno) && nzchar(trimws(input$aud_buscar_alumno))) {
    q <- norm_txt(trimws(input$aud_buscar_alumno))
    d <- d[grepl(q, norm_txt(d$Alumno), fixed = TRUE) | grepl(q, norm_txt(d$Profesor), fixed = TRUE), , drop = FALSE]
  }
  d
  
})

