output$plot_asist_notas <- renderPlot({
  d <- cruce_asist_notas()
  validate(need(nrow(d) > 0, "No hay alumnos vinculados entre asistencia y notas para esta selección."))
  
  es_individual <- (!is.null(input$select_curso) && input$select_curso != "TODOS")
  alumno_sel <- input$filtro_alumno_dispersion
  filtrado_alumno <- (!is.null(alumno_sel) && alumno_sel != "TODOS" && alumno_sel %in% d$Alumno)
  
  r <- suppressWarnings(cor(d$Asistencia, d$PG, use = "complete.obs"))
  r_txt <- if (is.na(r)) "s/d" else sprintf("%.2f", r)
  
  sub_txt <- if (filtrado_alumno) {
    d_ind <- d %>% filter(Alumno == alumno_sel)
    sprintf("Estudiante: %s | Asistencia: %.1f%% | Promedio: %.1f | %s",
            alumno_sel, d_ind$Asistencia[1], d_ind$PG[1], etiqueta_curso_segura(d_ind$Curso[1]))
  } else if (es_individual) {
    sprintf("%s | Correlación (Pearson): %s | %d alumnos", etiqueta_curso_segura(input$select_curso), r_txt, nrow(d))
  } else {
    sprintf("Todos los cursos | Correlación (Pearson): %s | %d alumnos", r_txt, nrow(d))
  }
  
  p <- ggplot() +
    annotate("rect", xmin = UMBRAL_ASIST, xmax = Inf, ymin = NOTA_ROJA, ymax = Inf, fill = "#2f6db5", alpha = 0.08) +
    annotate("rect", xmin = -Inf, xmax = UMBRAL_ASIST, ymin = -Inf, ymax = NOTA_ROJA, fill = "#d64550", alpha = 0.08) +
    annotate("rect", xmin = -Inf, xmax = UMBRAL_ASIST, ymin = NOTA_ROJA, ymax = Inf, fill = "#f0a030", alpha = 0.08) +
    annotate("rect", xmin = UMBRAL_ASIST, xmax = Inf, ymin = -Inf, ymax = NOTA_ROJA, fill = "#f0a030", alpha = 0.08) +
    geom_vline(xintercept = UMBRAL_ASIST, color = "#b02a37", linetype = "dashed", linewidth = 0.9) +
    geom_hline(yintercept = NOTA_ROJA, color = "#b02a37", linetype = "dashed", linewidth = 0.9) +
    annotate("text", x = Inf, y = Inf, label = "Cumple en todo", hjust = 1.1, vjust = 1.5,
             fontface = "bold", color = "#1e4f8f", alpha = 0.5, size = 3.6) +
    annotate("text", x = -Inf, y = Inf, label = "Riesgo de asistencia", hjust = -0.1, vjust = 1.5,
             fontface = "bold", color = "#b7791f", alpha = 0.5, size = 3.6) +
    annotate("text", x = -Inf, y = -Inf, label = "Doble riesgo", hjust = -0.1, vjust = -1.3,
             fontface = "bold", color = "#b02a37", alpha = 0.5, size = 3.6) +
    annotate("text", x = Inf, y = -Inf, label = "Riesgo académico", hjust = 1.1, vjust = -1.3,
             fontface = "bold", color = "#b7791f", alpha = 0.5, size = 3.6)
  
  if (filtrado_alumno) {
    d_target <- d %>% filter(Alumno == alumno_sel)
    if (identical(input$modo_filtro_dispersion, "DESTACAR")) {
      p <- p + geom_point(data = d %>% filter(Alumno != alumno_sel), aes(x = Asistencia, y = PG),
                          color = "#94a3b8", size = 3.5, alpha = 0.3)
    }
    p <- p +
      geom_point(data = d_target, aes(x = Asistencia, y = PG), color = "#0284c7", size = 6.5,
                 shape = 21, fill = "#38bdf8", stroke = 2) +
      ggrepel::geom_label_repel(data = d_target, aes(x = Asistencia, y = PG, label = Alumno),
                                size = 4.2, fontface = "bold", color = "#ffffff", fill = "#0f172a",
                                box.padding = 0.5, point.padding = 0.4, seed = 42)
  } else if (es_individual) {
    p <- p +
      geom_smooth(data = d, aes(x = Asistencia, y = PG), method = "lm", formula = y ~ x,
                  se = FALSE, color = "grey40", linetype = "dotted") +
      geom_point(data = d, aes(x = Asistencia, y = PG), color = col_azul, size = 4.4, alpha = 0.85)
    if (isTRUE(input$mostrar_todos_nombres)) {
      p <- p + ggrepel::geom_text_repel(
        data = d, aes(x = Asistencia, y = PG, label = Alumno), size = 3.2, fontface = "bold",
        color = "#1e293b", box.padding = 0.35, point.padding = 0.3,
        segment.color = "#94a3b8", segment.size = 0.35, max.overlaps = 50, seed = 42)
    }
  } else {
    d$Etiqueta_Curso <- etiquetar(d$Curso)
    p <- p +
      geom_smooth(data = d, aes(x = Asistencia, y = PG), method = "lm", formula = y ~ x,
                  se = FALSE, color = "grey40", linetype = "dotted") +
      geom_point(data = d, aes(x = Asistencia, y = PG, color = Etiqueta_Curso), size = 3.2, alpha = 0.75)
  }
  
  p +
    scale_y_continuous(limits = c(1, 7.6), breaks = 1:7) +
    labs(title = "Asistencia vs. rendimiento académico",
         subtitle = paste0(sub_txt, "\nAzul = cumple en todo | Amarillo = riesgo en una variable | Rojo = doble riesgo"),
         x = "% de asistencia anual", y = "Promedio de notas (1.0 - 7.0)", color = "Curso") +
    tema_dash() +
    theme(legend.position = if (es_individual || filtrado_alumno) "none" else "bottom")
  
})

