fila_perfil <- reactive({
  req(input$select_alumno, input$select_curso)
  m <- maestro()
  f <- m %>% filter(Alumno == input$select_alumno)
  if (input$select_curso != "TODOS") f <- f %>% filter(Curso == input$select_curso)
  f
