output$perfil_resumen <- renderUI({
  validate(need(asist_cargada() || notas_cargadas() || pdd_cargado() || dia_cargado(), "Carga datos para ver el perfil del alumno."))
  f <- fila_perfil()
  validate(need(nrow(f) > 0, "No hay datos integrados para este alumno."))
  f <- f[1, ]
  chip <- function(txt, riesgo, disponible) {
    cl <- if (!disponible) "chip-na" else if (isTRUE(riesgo)) "chip-red" else "chip-ok"
    span(class = paste("chip", cl), txt)
  }
  div(class = "perfil-header",
      div(class = "perfil-nombre", f$Alumno),
      div(class = "perfil-curso", etiqueta_curso_segura(f$Curso)),
      div(
        chip(if (is.na(f$Asistencia)) "Asistencia: s/d" else sprintf("Asistencia %.1f%%", f$Asistencia), f$Riesgo_Asist, !is.na(f$Asistencia)),
        chip(if (is.na(f$PG)) "Notas: s/d" else sprintf("Promedio %.1f (%d en rojo)", f$PG, f$N_Rojas), f$Riesgo_Nota, !is.na(f$PG)),
        chip(if (is.na(f$Logro_PDD)) "Diagnóstico: s/d" else sprintf("Logro Diagnóstico %.0f%%", f$Logro_PDD), f$Riesgo_PDD, !is.na(f$Logro_PDD)),
        if (!is.na(f$MaxRacha) && f$MaxRacha >= 3) span(class = "chip chip-red", sprintf("Racha de %d faltas seguidas", f$MaxRacha))
      ),
      div(style = "margin-top:6px; opacity:.85;",
          paste("Factores de riesgo:", texto_factores(f$Riesgo_Asist, f$Riesgo_Nota, f$Riesgo_PDD))))
})

