perfil_asig <- reactive({
  req(input$select_alumno, input$select_curso)
  al <- input$select_alumno
  
  n_det <- det_filtrado() %>% filter(Alumno == al)
  if (input$select_curso != "TODOS") n_det <- n_det %>% filter(Curso == input$select_curso)
  n_ev_res <- if (nrow(n_det) > 0) {
    n_det %>%
      group_by(Asignatura) %>%
      summarise(Detalle_Evals = paste0(Evaluacion_Nombre, ": ", sprintf("%.1f", Nota), collapse = " | "),
                .groups = "drop")
  } else data.frame(Asignatura = character(), Detalle_Evals = character(), stringsAsFactors = FALSE)
  
  n <- prom_base() %>% filter(Alumno == al)
  if (input$select_curso != "TODOS") n <- n %>% filter(Curso == input$select_curso)
  n <- n %>%
    left_join(n_ev_res, by = "Asignatura") %>%
    mutate(Clave = asig_clave(Asignatura)) %>%
    group_by(Clave) %>%
    summarise(Asignatura_Real = paste(unique(Asignatura), collapse = " / "),
              Profesor = paste(unique(Profesor), collapse = " / "),
              Nota_Colegio = mean(Promedio),
              Evaluaciones = paste(na.omit(unique(Detalle_Evals)), collapse = " || "),
              .groups = "drop")
  
  p <- pdd_data() %>% filter(Alumno_Canon == al)
  if (input$select_curso != "TODOS") p <- p %>% filter(Curso_Canon == input$select_curso)
  p <- p %>%
    mutate(Clave = asig_clave(Asignatura)) %>%
    group_by(Clave) %>%
    summarise(Nota_PDD = mean(Nota, na.rm = TRUE), Logro = mean(Logro, na.rm = TRUE), .groups = "drop")
  
  d_dia <- dia_data()$res %>% filter(Alumno_Canon == al)
  if (input$select_curso != "TODOS") d_dia <- d_dia %>% filter(Curso_Canon == input$select_curso)
  d_dia <- d_dia %>%
    mutate(Clave = asig_clave(Asignatura)) %>%
    group_by(Clave) %>%
    summarise(Logro_DIA = mean(Promedio_Logro, na.rm = TRUE),
              Nivel_DIA = last(Nivel_DIA),
              Eje_Debil_DIA = last(Eje_Debil), .groups = "drop")
  
  full_join(n, p, by = "Clave") %>% full_join(d_dia, by = "Clave")
  
})

