pdd_vs_notas <- reactive({
  validate(need(pdd_cargado() && notas_cargadas(), "Sube notas y PDD para compararlos."))
  n <- prom_base() %>%
    mutate(Clave = asig_clave(Asignatura)) %>%
    group_by(Curso, Alumno, Clave) %>%
    summarise(Nota_Colegio = mean(Promedio), .groups = "drop")
  p <- pdd_data() %>%
    filter(!is.na(Nota)) %>%
    mutate(Clave = asig_clave(Asignatura)) %>%
    group_by(Curso = Curso_Canon, Alumno = Alumno_Canon, Clave) %>%
    summarise(Nota_PDD = mean(Nota), Logro = mean(Logro, na.rm = TRUE), .groups = "drop")
  d <- inner_join(n, p, by = c("Curso", "Alumno", "Clave")) %>%
    mutate(Diferencia = Nota_Colegio - Nota_PDD)
  if (!is.null(input$select_curso) && input$select_curso != "TODOS") d <- d %>% filter(Curso == input$select_curso)
  d
})

