output$plot_notas_alumno <- renderPlot({
  validate(need(notas_cargadas(), "Sube planillas de notas primero."))
  p_raw <- prom_curso()
  validate(need(nrow(p_raw) > 0, "Sin notas para la selección actual."))
  
  if (identical(input$modo_barras_epoca, "CONSOLIDADO")) {
    d <- p_raw %>%
      filter(es_nombre_alumno(Alumno)) %>%
      group_by(Alumno) %>%
      summarise(
        PG = round(mean(Promedio, na.rm = TRUE), 1),
        Epocas = paste(sort(unique(sprintf("%s-S%s", Anio, Semestre))), collapse = ", "),
        .groups = "drop"
      ) %>%
      mutate(Situacion = ifelse(PG < NOTA_ROJA, "Bajo 4.0", "Aprobado"))
    
    ggplot(d, aes(x = reorder(Alumno, PG), y = PG, fill = Situacion)) +
      geom_col(width = 0.7) +
      geom_hline(yintercept = NOTA_ROJA, color = col_rojo, linetype = "dashed") +
      geom_text(aes(label = sprintf("%.1f (%s)", PG, Epocas)), hjust = -0.08, fontface = "bold", size = 3.3) +
      coord_flip() +
      scale_fill_manual(values = c("Aprobado" = col_azul, "Bajo 4.0" = col_rojo)) +
      scale_y_continuous(limits = c(0, 8.2), breaks = 0:7) +
      labs(x = NULL, y = "Promedio general consolidado", fill = NULL) +
      tema_dash() +
      theme(legend.position = "top", axis.text.y = element_text(size = 9.5))
  } else {
    d <- pg_alumno_epoca(p_raw) %>%
      group_by(Alumno, Epoca) %>%
      summarise(PG = round(mean(PG), 1), .groups = "drop")
    
    niveles_ep <- c("2025 · S1", "2025 · S2", "2026 · S1", "2026 · S2")
    ep_extra <- setdiff(sort(unique(d$Epoca)), niveles_ep)
    d$Epoca <- factor(d$Epoca, levels = c(niveles_ep, ep_extra))
    
    colores_ep <- c(
      "2025 · S1" = "#7fb3e0",
      "2025 · S2" = "#2f6db5",
      "2026 · S1" = "#14a3a0",
      "2026 · S2" = "#1e4f8f"
    )
    
    ord_al <- d %>% group_by(Alumno) %>% summarise(M = mean(PG), .groups = "drop")
    d <- left_join(d, ord_al, by = "Alumno")
    
    ggplot(d, aes(x = reorder(Alumno, M), y = PG, fill = Epoca)) +
      geom_col(position = position_dodge(width = 0.8), width = 0.72) +
      geom_hline(yintercept = NOTA_ROJA, color = col_rojo, linetype = "dashed") +
      geom_text(aes(label = sprintf("%.1f", PG)),
                position = position_dodge(width = 0.8),
                hjust = -0.15, fontface = "bold", size = 3.1) +
      coord_flip() +
      scale_fill_manual(values = colores_ep, na.value = "#8e6bbf", drop = TRUE) +
      scale_y_continuous(limits = c(0, 7.8), breaks = 0:7) +
      labs(x = NULL, y = "Promedio por época (Año · Semestre)", fill = "Época (Año · Semestre)") +
      tema_dash() +
      theme(legend.position = "top", axis.text.y = element_text(size = 9.5))
  }
})

