# Rangos de notas por asignatura (con clic para ver alumnos)
asig_rango_data <- reactive({
  d_prom <- prom_curso_nc()
  if (nrow(d_prom) == 0) return(NULL)
  d <- d_prom %>%
    mutate(Rango = rangos_nota(Promedio)) %>%
    count(Asignatura, Rango) %>%
    group_by(Asignatura) %>%
    mutate(Total = sum(n), Pct = n / Total * 100) %>%
    ungroup()
  
  niveles <- sort(unique(d$Asignatura), decreasing = TRUE)
  d$Asignatura <- factor(d$Asignatura, levels = niveles)
  list(d = d, niveles = niveles, d_prom = d_prom)
})

