observeEvent(input$click_asig_rango, {
  clk <- input$click_asig_rango
  req(clk, notas_cargadas())
  r <- asig_rango_data()
  req(!is.null(r))
  
  idx_y <- round(clk$y)
  if (is.na(idx_y) || idx_y < 1 || idx_y > length(r$niveles)) return()
  asig_sel <- r$niveles[idx_y]
  
  sub_d <- r$d %>% filter(as.character(Asignatura) == asig_sel)
  total_n <- sum(sub_d$n)
  if (total_n == 0) return()
  
  cuenta <- function(rg) sum(sub_d$n[as.character(sub_d$Rango) == rg])
  lim1 <- cuenta("6.0-7.0") / total_n
  lim2 <- (cuenta("6.0-7.0") + cuenta("5.0-5.9")) / total_n
  lim3 <- (cuenta("6.0-7.0") + cuenta("5.0-5.9") + cuenta("4.0-4.9")) / total_n
  
  rango_sel <- if (clk$x <= lim1) {
    "6.0-7.0"
  } else if (clk$x <= lim2) {
    "5.0-5.9"
  } else if (clk$x <= lim3) {
    "4.0-4.9"
  } else {
    "< 4.0"
  }
  
  df_asig <- r$d_prom %>%
    filter(Asignatura == asig_sel, es_nombre_alumno(Alumno)) %>%
    mutate(Rango = as.character(rangos_nota(Promedio)))
  
  datos_modal_asig_rango(list(asig = asig_sel, df = df_asig))
  
  showModal(modalDialog(
    title = paste("Desempeño en", asig_sel),
    div(
      class = "mb-3",
      selectInput(
        "modal_select_asig_rango", "Filtrar estudiantes por nivel de desempeño:",
        choices = c(
          "Todos los estudiantes de la asignatura" = "TODOS",
          "Les fue muy bien / Destacado (6.0 - 7.0)" = "6.0-7.0",
          "Les fue medianamente bien / Adecuado (5.0 - 5.9)" = "5.0-5.9",
          "Regular / En riesgo (4.0 - 4.9)" = "4.0-4.9",
          "Les fue mal / Nota Roja (< 4.0)" = "< 4.0"
        ),
        selected = rango_sel, width = "100%"
      )
    ),
    div(class = "scroll-box", tableOutput("tabla_modal_asig_rango")),
    easyClose = TRUE, size = "l", footer = modalButton("Cerrar")
  ))
})

