# Evolución de notas por evaluación
output$plot_notas_evolucion <- renderPlot({
  validate(need(notas_cargadas(), "Sube planillas de notas primero."))
  req(input$select_curso)
  dd <- det_filtrado()
  if (input$select_curso != "TODOS") dd <- dd %>% filter(Curso == input$select_curso)
  if (!is.null(input$nc_filtro_asigs) && length(input$nc_filtro_asigs) > 0) {
    dd <- dd %>% filter(Asignatura %in% input$nc_filtro_asigs)
  }
  validate(need(nrow(dd) > 0, "Sin evaluaciones registradas para las asignaturas seleccionadas."))
  
  modo <- if (is.null(input$nc_modo_evol)) "SECUENCIA" else input$nc_modo_evol
  n_asigs <- length(unique(dd$Asignatura))
  
  if (modo == "EXACTO") {
    # Modo exacto: nombre real de cada prueba
    d <- dd %>%
      group_by(Asignatura, Semestre, Evaluacion, Etiqueta, Evaluacion_Nombre) %>%
      summarise(Prom = mean(Nota, na.rm = TRUE), .groups = "drop") %>%
      arrange(Semestre, Evaluacion)
    d$Eje_X <- factor(d$Etiqueta, levels = unique(d$Etiqueta))
    d$Texto_Punto <- sprintf("%.1f", d$Prom)
  } else {
    # Modo secuencia: eje homologado (S1 · Eval 1, S1 · Eval 2...)
    d <- dd %>%
      mutate(Etiqueta_Lim = sprintf("S%d · Eval %d", Semestre, Evaluacion)) %>%
      group_by(Asignatura, Semestre, Evaluacion, Etiqueta_Lim) %>%
      summarise(
        Prom = mean(Nota, na.rm = TRUE),
        Nombre_Real = first(Evaluacion_Nombre),
        .groups = "drop"
      ) %>%
      arrange(Semestre, Evaluacion)
    d$Eje_X <- factor(d$Etiqueta_Lim, levels = unique(d$Etiqueta_Lim))
    d$Texto_Punto <- if (n_asigs <= 3 || modo == "FACETAS") {
      sprintf("%.1f\n(%s)", d$Prom, substr(d$Nombre_Real, 1, 12))
    } else {
      sprintf("%.1f", d$Prom)
    }
  }
  
  p <- ggplot(d, aes(x = Eje_X, y = Prom, color = Asignatura, group = Asignatura)) +
    geom_hline(yintercept = NOTA_ROJA, color = col_rojo, linetype = "dashed", linewidth = 0.8) +
    geom_line(linewidth = 1.2, alpha = 0.85) +
    geom_point(size = 3.2) +
    scale_color_manual(values = paleta_cat) +
    scale_y_continuous(limits = c(1, 7.7), breaks = 1:7) +
    tema_dash()
  
  if (modo == "FACETAS") {
    p +
      geom_text(aes(label = sprintf("%.1f", Prom)), vjust = -0.8, fontface = "bold", size = 3.3, show.legend = FALSE) +
      facet_wrap(~Asignatura, scales = "free_x") +
      labs(
        title = "Evolución de evaluaciones separada por asignatura",
        subtitle = "Cada recuadro muestra la tendencia limpia de una asignatura de principio a fin",
        x = NULL, y = "Promedio de la evaluación (1.0 - 7.0)"
      ) +
      theme(legend.position = "none", axis.text.x = element_text(angle = 25, hjust = 1, size = 9))
  } else {
    p +
      ggrepel::geom_text_repel(
        aes(label = Texto_Punto), fontface = "bold", size = 3.3,
        box.padding = 0.25, max.overlaps = 25, show.legend = FALSE
      ) +
      labs(
        title = if (input$select_curso != "TODOS") paste("Evolución de notas -", etiqueta_curso_segura(input$select_curso)) else "Evolución de notas por número de evaluación",
        subtitle = "Eje horizontal unificado por orden de evaluación (Eval 1, Eval 2, Eval 3...) para comparar asignaturas sin cruces confusos",
        x = "Secuencia de Evaluaciones del Semestre", y = "Promedio de evaluación (1.0 - 7.0)", color = "Asignatura"
      ) +
      theme(legend.position = "top", axis.text.x = element_text(angle = 20, hjust = 1, face = "bold", size = 10))
  }
})

