  updateSelectInput(session, "dia_filtro_curso", choices = c("Todos", sort(unique(d$Curso))), selected = "Todos")
})

# Filtros DIA en cascada
observe({
  req(dia_cargado())
  d_all <- dia_data()$res
  if (nrow(d_all) == 0) return()
  
  cur_anio  <- if (is.null(input$dia_filtro_anio)) "Todos" else input$dia_filtro_anio
  cur_etapa <- if (is.null(input$dia_filtro_etapa)) "Todas" else input$dia_filtro_etapa
  cur_asig  <- if (is.null(input$dia_filtro_asig)) "Todas" else input$dia_filtro_asig
  cur_curso <- if (is.null(input$dia_filtro_curso)) "Todos" else input$dia_filtro_curso
  
  # Opciones de año
  d_an <- d_all
  if (cur_etapa != "Todas") d_an <- d_an %>% filter(Etapa == cur_etapa)
  if (cur_asig  != "Todas") d_an <- d_an %>% filter(Asignatura == cur_asig)
  if (cur_curso != "Todos") d_an <- d_an %>% filter(Curso == cur_curso)
  u_an <- sort(unique(na.omit(d_an$Anio)), decreasing = TRUE)
  choices_an <- c("Todos", as.character(u_an))
  sel_an <- if (cur_anio %in% as.character(u_an)) cur_anio else "Todos"
  
  # Opciones de etapa
  d_et <- d_all
  if (cur_anio  != "Todos") d_et <- d_et %>% filter(Anio == as.integer(cur_anio))
  if (cur_asig  != "Todas") d_et <- d_et %>% filter(Asignatura == cur_asig)
  if (cur_curso != "Todos") d_et <- d_et %>% filter(Curso == cur_curso)
  u_et <- sort(unique(d_et$Etapa))
  choices_et <- c("Todas", u_et)
  sel_et <- if (cur_etapa %in% u_et) cur_etapa else "Todas"
  
  # Opciones de asignatura
  d_as <- d_all
  if (cur_anio  != "Todos") d_as <- d_as %>% filter(Anio == as.integer(cur_anio))
  if (cur_etapa != "Todas") d_as <- d_as %>% filter(Etapa == cur_etapa)
  if (cur_curso != "Todos") d_as <- d_as %>% filter(Curso == cur_curso)
  u_as <- sort(unique(d_as$Asignatura))
  choices_as <- c("Todas", u_as)
  sel_as <- if (cur_asig %in% u_as) cur_asig else "Todas"
  
  # Opciones de curso
  d_cu <- d_all
  if (cur_anio  != "Todos") d_cu <- d_cu %>% filter(Anio == as.integer(cur_anio))
  if (cur_etapa != "Todas") d_cu <- d_cu %>% filter(Etapa == cur_etapa)
  if (cur_asig  != "Todas") d_cu <- d_cu %>% filter(Asignatura == cur_asig)
  u_cu <- sort(unique(d_cu$Curso))
  choices_cu <- c("Todos", u_cu)
  sel_cu <- if (cur_curso %in% u_cu) cur_curso else "Todos"
  
  if (!identical(choices_an, dia_prev_an_choices) || !identical(sel_an, dia_prev_an_sel)) {
    dia_prev_an_choices <<- choices_an; dia_prev_an_sel <<- sel_an
    updateSelectInput(session, "dia_filtro_anio", choices = choices_an, selected = sel_an)
  }
  if (!identical(choices_et, dia_prev_et_choices) || !identical(sel_et, dia_prev_et_sel)) {
    dia_prev_et_choices <<- choices_et; dia_prev_et_sel <<- sel_et
    updateSelectInput(session, "dia_filtro_etapa", choices = choices_et, selected = sel_et)
  }
  if (!identical(choices_as, dia_prev_as_choices) || !identical(sel_as, dia_prev_as_sel)) {
    dia_prev_as_choices <<- choices_as; dia_prev_as_sel <<- sel_as
    updateSelectInput(session, "dia_filtro_asig", choices = choices_as, selected = sel_as)
  }
  if (!identical(choices_cu, dia_prev_cu_choices) || !identical(sel_cu, dia_prev_cu_sel)) {
    dia_prev_cu_choices <<- choices_cu; dia_prev_cu_sel <<- sel_cu
    updateSelectInput(session, "dia_filtro_curso", choices = choices_cu, selected = sel_cu)
  }
})

# Datos DIA filtrados (alimentan tablas y gráficos)
dia_filtrado <- reactive({
  dd <- dia_data()
  r <- dd$res; e <- dd$ejes
  if (nrow(r) == 0) return(dd)
  
  anio_val  <- input$dia_filtro_anio
  etapa_val <- input$dia_filtro_etapa
  asig_val  <- input$dia_filtro_asig
  curso_val <- input$dia_filtro_curso
  
  if (!is.null(anio_val) && anio_val != "Todos") {
    a_num <- suppressWarnings(as.integer(anio_val))
    if (!is.na(a_num)) {
      r <- r %>% filter(Anio == a_num)
      if ("Anio" %in% names(e)) {
        e <- e %>% filter(Anio == a_num)
      } else {
        e <- e %>% filter(as.integer(substr(Anio_Mes, 1, 4)) == a_num)
      }
    }
  }
  if (!is.null(etapa_val) && etapa_val != "Todas" && etapa_val %in% r$Etapa) {
    r <- r %>% filter(Etapa == etapa_val)
    e <- e %>% filter(Etapa == etapa_val)
  }
  if (!is.null(asig_val) && asig_val != "Todas" && asig_val %in% r$Asignatura) {
    r <- r %>% filter(Asignatura == asig_val)
    e <- e %>% filter(Asignatura == asig_val)
  }
  if (!is.null(curso_val) && curso_val != "Todos" && curso_val %in% r$Curso) {
    r <- r %>% filter(Curso == curso_val)
    e <- e %>% filter(Curso == curso_val)
  }
  list(res = r, ejes = e)
})

