# Ventana con los estudiantes de un nivel DIA
abrir_modal_dia_nivel <- function(nivel_objetivo, periodo_sel = NULL, asig_sel = NULL, curso_sel = NULL) {
  r <- dia_filtrado()$res
  req(nrow(r) > 0)
  
  datos_modal_dia_nivel(list(nivel = nivel_objetivo, df = r))
  
  periodos_u <- sort(unique(r$Etiqueta_Fecha), decreasing = TRUE)
  asigs_u    <- sort(unique(r$Asignatura))
  cursos_u   <- sort(unique(r$Curso))
  
  sel_periodo <- if (!is.null(periodo_sel) && periodo_sel %in% periodos_u) periodo_sel else "Todos los períodos evaluados"
  sel_asig    <- if (!is.null(asig_sel) && asig_sel %in% asigs_u) asig_sel else "Todas"
  sel_curso   <- if (!is.null(curso_sel) && curso_sel %in% cursos_u) curso_sel else "Todos los cursos"
  
  titulo_modal <- paste("Estudiantes en", nivel_objetivo,
                        if (!is.null(asig_sel) && asig_sel != "Todas") paste("—", asig_sel) else "— Diagnóstico DIA")
  
  showModal(modalDialog(
    title = titulo_modal,
    div(
      class = "mb-3",
      layout_columns(
        col_widths = c(3, 3, 3, 3),
        selectInput("modal_filtro_dia_nivel", "Nivel de logro:",
                    choices = niveles_dia, selected = nivel_objetivo),
        selectInput("modal_filtro_dia_asig", "Asignatura:",
                    choices = c("Todas", asigs_u), selected = sel_asig),
        selectInput("modal_filtro_dia_periodo", "Período / Año:",
                    choices = c("Todos los períodos evaluados", periodos_u), selected = sel_periodo),
        selectInput("modal_filtro_dia_curso", "Curso:",
                    choices = c("Todos los cursos", cursos_u), selected = sel_curso)
      )
    ),
    uiOutput("modal_dia_contador"),
    div(class = "scroll-box", tableOutput("tabla_modal_click_dia_niveles")),
    easyClose = TRUE, size = "xl", footer = modalButton("Cerrar")
  ))
}

