# Clic en el gráfico de barras DIA
observeEvent(input$click_dia_niveles, {
  clk <- input$click_dia_niveles
  req(clk, dia_cargado())
  r <- dia_filtrado()$res %>% filter(!is.na(Nivel_DIA))
  req(nrow(r) > 0)
  
  cnt <- r %>%
    mutate(Grupo = paste0(Curso, " · ", Asignatura, "\n(", Anio_Mes, " ", Etapa, ")")) %>%
    count(Grupo, Curso, Asignatura, Anio_Mes, Etapa, Etiqueta_Fecha, Nivel_DIA) %>%
    group_by(Grupo) %>%
    mutate(Total = sum(n)) %>%
    ungroup()
  
  niveles_grupo <- cnt %>%
    distinct(Grupo, Anio_Mes, Asignatura) %>%
    arrange(Anio_Mes, Asignatura) %>%
    pull(Grupo)
  
  idx_y <- round(clk$y)
  if (is.na(idx_y) || idx_y < 1 || idx_y > length(niveles_grupo)) return()
  g_sel <- niveles_grupo[idx_y]
  
  sub_cnt <- cnt %>% filter(Grupo == g_sel)
  tot <- sub_cnt$Total[1]
  if (is.na(tot) || tot == 0) return()
  
  curso_bar   <- sub_cnt$Curso[1]
  asig_bar    <- sub_cnt$Asignatura[1]
  periodo_bar <- sub_cnt$Etiqueta_Fecha[1]
  
  n_n3 <- sum(sub_cnt$n[sub_cnt$Nivel_DIA == "Nivel III (Satisfactorio)"])
  n_n2 <- sum(sub_cnt$n[sub_cnt$Nivel_DIA == "Nivel II (Parcial)"])
  n_n1 <- sum(sub_cnt$n[sub_cnt$Nivel_DIA == "Nivel I (No logrado)"])
  
  lim_n3 <- n_n3 / tot
  lim_n2 <- (n_n3 + n_n2) / tot
  
  nivel_detectado <- if (clk$x <= lim_n3) {
    "Nivel III (Satisfactorio)"
  } else if (clk$x <= lim_n2) {
    "Nivel II (Parcial)"
  } else {
    "Nivel I (No logrado)"
  }
  
  abrir_modal_dia_nivel(
    nivel_objetivo = nivel_detectado,
    periodo_sel    = periodo_bar,
    asig_sel       = asig_bar,
    curso_sel      = curso_bar
  )
})

