# Línea de tiempo longitudinal DIA (2025 vs 2026)
output$plot_dia_evolucion <- renderPlot({
  validate(need(dia_cargado(), "Sube archivos Excel del DIA."))
  r <- dia_filtrado()$res
  e <- dia_filtrado()$ejes
  validate(need(nrow(r) > 0 && nrow(e) > 0, "Sin datos para graficar evolución."))
  
  modo <- if (is.null(input$dia_tipo_evol)) "COMP_DEBIL" else input$dia_tipo_evol
  
  res_periodos <- r %>%
    mutate(Anio_Val = if ("Anio" %in% names(.)) Anio else as.integer(substr(Anio_Mes, 1, 4)),
           Periodo_Etiq = sprintf("%d\n%s", Anio_Val, Etapa)) %>%
    distinct(Anio_Mes, Anio_Val, Etapa, Periodo_Etiq) %>%
    arrange(Anio_Mes)
  
  niveles_cronologicos <- res_periodos$Periodo_Etiq
  
  # Modo 1: logro general vs eje más débil
  if (modo == "COMP_DEBIL") {
    prom_gral <- r %>%
      mutate(Anio_Val = if ("Anio" %in% names(.)) Anio else as.integer(substr(Anio_Mes, 1, 4)),
             Periodo_Etiq = sprintf("%d\n%s", Anio_Val, Etapa)) %>%
      group_by(Periodo_Etiq, Anio_Mes, Asignatura) %>%
      summarise(Logro = mean(Promedio_Logro, na.rm = TRUE), .groups = "drop") %>%
      mutate(Serie = "Logro Promedio General",
             Etiqueta_Txt = sprintf("%.1f%%", Logro))
    
    eje_peor <- e %>%
      mutate(Anio_Val = as.integer(substr(Anio_Mes, 1, 4)),
             Periodo_Etiq = sprintf("%d\n%s", Anio_Val, Etapa)) %>%
      group_by(Periodo_Etiq, Anio_Mes, Asignatura, Eje) %>%
      summarise(Media_Eje = mean(Logro, na.rm = TRUE), .groups = "drop") %>%
      group_by(Periodo_Etiq, Anio_Mes, Asignatura) %>%
      arrange(Media_Eje) %>%
      slice(1) %>%
      ungroup() %>%
      transmute(Periodo_Etiq, Anio_Mes, Asignatura,
                Logro = Media_Eje,
                Serie = "Eje Más Descendido (Piso)",
                Etiqueta_Txt = sprintf("%s\n%.1f%%", Eje, Media_Eje))
    
    prom_gral$Periodo_Etiq <- factor(prom_gral$Periodo_Etiq, levels = niveles_cronologicos)
    eje_peor$Periodo_Etiq  <- factor(eje_peor$Periodo_Etiq, levels = niveles_cronologicos)
    
    p <- ggplot() +
      geom_hline(yintercept = 50, color = "#cbd5e1", linetype = "dotted", linewidth = 0.8) +
      
      geom_line(data = prom_gral, aes(x = Periodo_Etiq, y = Logro, group = Asignatura),
                color = col_azul, linewidth = 1.3) +
      geom_point(data = prom_gral, aes(x = Periodo_Etiq, y = Logro),
                 color = "#1e4f8f", size = 4) +
      geom_text(data = prom_gral, aes(x = Periodo_Etiq, y = Logro, label = Etiqueta_Txt),
