      geom_line(data = eje_peor, aes(x = Periodo_Etiq, y = Logro, group = Asignatura),
                color = "#dc2626", linewidth = 1.2, linetype = "dashed") +
      geom_point(data = eje_peor, aes(x = Periodo_Etiq, y = Logro),
                 color = "#991b1b", size = 3.8) +
      ggrepel::geom_label_repel(
        data = eje_peor, aes(x = Periodo_Etiq, y = Logro, label = Etiqueta_Txt),
        fontface = "bold", size = 3.1, color = "#991b1b", fill = "#fff5f5",
        direction = "y", box.padding = 0.4, point.padding = 0.3, segment.size = 0.3
      ) +
      
      scale_y_continuous(limits = c(0, 110), breaks = seq(0, 100, 20)) +
      labs(
        title = "Trayectoria DIA: Logro Promedio General vs. Eje Más Descendido (2025 - 2026)",
        subtitle = "Línea azul: Promedio del curso en cada prueba | Línea roja discontinua: El eje más débil detectado en esa fecha",
        x = "Fecha de aplicación (Año y Etapa)",
        y = "% de Logro"
