      tema_dash() +
      theme(
        axis.text.x = element_text(face = "bold", size = 9.5, lineheight = 0.95),
        strip.text = element_text(face = "bold", size = 11)
      )
    
    if (length(unique(prom_gral$Asignatura)) > 1) {
      p + facet_wrap(~Asignatura, ncol = 2)
    } else {
      p
    }
    
    # Modo 2: todos los ejes temáticos
  } else if (modo == "TODOS_EJES") {
    evo_ejes <- e %>%
      mutate(Anio_Val = as.integer(substr(Anio_Mes, 1, 4)),
             Periodo_Etiq = sprintf("%d\n%s", Anio_Val, Etapa)) %>%
      group_by(Periodo_Etiq, Asignatura, Eje) %>%
      summarise(Logro = mean(Logro, na.rm = TRUE), .groups = "drop")
    
