      p + facet_wrap(~Asignatura, ncol = 2)
    } else {
      p
    }
    
    # Modo 3: por curso
  } else {
    evo_c <- r %>%
      mutate(Anio_Val = if ("Anio" %in% names(.)) Anio else as.integer(substr(Anio_Mes, 1, 4)),
             Periodo_Etiq = sprintf("%d\n%s", Anio_Val, Etapa)) %>%
      group_by(Periodo_Etiq, Curso, Asignatura) %>%
      summarise(Logro = mean(Promedio_Logro, na.rm = TRUE), .groups = "drop")
    
    evo_c$Periodo_Etiq <- factor(evo_c$Periodo_Etiq, levels = niveles_cronologicos)
    
    ggplot(evo_c, aes(x = Periodo_Etiq, y = Logro, color = Curso, group = interaction(Curso, Asignatura))) +
      geom_line(linewidth = 1.2) +
      geom_point(size = 3.8) +
      geom_text(aes(label = sprintf("%.1f%%", Logro)), vjust = -1, fontface = "bold", size = 3.4, show.legend = FALSE) +
      scale_y_continuous(limits = c(0, 110), breaks = seq(0, 100, 20)) +
      scale_color_manual(values = paleta_cat) +
      labs(
        title = "Evolución DIA comparada por Curso",
        x = "Fecha de aplicación (Año y Etapa)",
        y = "% Logro promedio",
        color = "Curso:"
      ) +
      tema_dash() +
      theme(
        legend.position = "top",
        axis.text.x = element_text(face = "bold", size = 9.5, lineheight = 0.95)
      )
  }
})

