# Mapa de calor DIA: cascada de filtros (curso > asignatura > fecha)

# Cursos disponibles
observeEvent(dia_data(), {
  req(dia_cargado())
  e <- dia_data()$ejes
  if (nrow(e) == 0) return()
  
  cursos_dia <- sort(unique(e$Curso))
  sel_c <- if (!is.null(input$dia_mapa_curso) && input$dia_mapa_curso %in% cursos_dia) {
    input$dia_mapa_curso
  } else {
    cursos_dia[1]
  }
  updateSelectInput(session, "dia_mapa_curso", choices = cursos_dia, selected = sel_c)
})

# Asignaturas del curso elegido
observeEvent(input$dia_mapa_curso, {
  req(dia_cargado(), input$dia_mapa_curso)
  e <- dia_data()$ejes %>% filter(Curso == input$dia_mapa_curso)
  if (nrow(e) == 0) return()
  
  asigs <- sort(unique(e$Asignatura))
  sel_a <- if (!is.null(input$dia_mapa_asig) && input$dia_mapa_asig %in% asigs) {
    input$dia_mapa_asig
  } else {
    asigs[1]
  }
  updateSelectInput(session, "dia_mapa_asig", choices = asigs, selected = sel_a)
})

# Fechas de la asignatura elegida
observeEvent(list(input$dia_mapa_curso, input$dia_mapa_asig), {
  req(dia_cargado(), input$dia_mapa_curso, input$dia_mapa_asig)
  e <- dia_data()$ejes %>%
    filter(Curso == input$dia_mapa_curso, Asignatura == input$dia_mapa_asig)
  if (nrow(e) == 0) return()
  
  periodos <- e %>%
    distinct(Anio_Mes, Etapa) %>%
    arrange(desc(Anio_Mes)) %>%
    mutate(Label = sprintf("%s (%s)", Anio_Mes, Etapa))
  
  choices_f <- stats::setNames(periodos$Anio_Mes, periodos$Label)
  sel_f <- if (!is.null(input$dia_mapa_fecha) && input$dia_mapa_fecha %in% periodos$Anio_Mes) {
    input$dia_mapa_fecha
  } else {
    periodos$Anio_Mes[1]
  }
  updateSelectInput(session, "dia_mapa_fecha", choices = choices_f, selected = sel_f)
})

# Mapa de calor por estudiante y eje (Figura 1 del informe DIA)
output$plot_dia_mapa_alumnos <- renderPlot({
  validate(need(dia_cargado(), "Sube archivos Excel del DIA."))
  req(input$dia_mapa_curso, input$dia_mapa_asig, input$dia_mapa_fecha)
  
  e <- dia_data()$ejes
  
  e_sub <- e %>%
    filter(
      Curso == input$dia_mapa_curso,
      Asignatura == input$dia_mapa_asig,
      Anio_Mes == input$dia_mapa_fecha
    ) %>%
    distinct(Alumno, Eje, .keep_all = TRUE)
  
  validate(need(nrow(e_sub) > 0, "No hay evaluaciones registradas para la combinación seleccionada."))
  
  prom_alumno <- e_sub %>%
    group_by(Alumno) %>%
    summarise(Prom_Total = mean(Logro, na.rm = TRUE), .groups = "drop")
  e_sub <- left_join(e_sub, prom_alumno, by = "Alumno")
  
  orden_sel <- if (is.null(input$dia_mapa_orden)) "ASC" else input$dia_mapa_orden
  
  if (orden_sel == "DESC") {
    e_sub$Alumno_Ord <- reorder(e_sub$Alumno, e_sub$Prom_Total)
  } else if (orden_sel == "ALFA") {
    e_sub$Alumno_Ord <- factor(e_sub$Alumno, levels = rev(sort(unique(e_sub$Alumno))))
  } else {
    e_sub$Alumno_Ord <- reorder(e_sub$Alumno, -e_sub$Prom_Total)
  }
  
  n_estudiantes <- length(unique(e_sub$Alumno))
  etapa_nombre <- e_sub$Etapa[1]
  
  ggplot(e_sub, aes(x = Eje, y = Alumno_Ord, fill = Logro)) +
    geom_tile(color = "white", linewidth = 0.6) +
    geom_text(aes(label = sprintf("%.0f%%", Logro)), size = 3.2, fontface = "bold") +
    scale_fill_gradient2(low = "#d64550", mid = "#f8fafc", high = "#1e4f8f",
                         midpoint = 50, limits = c(0, 100), name = "% Logro") +
    labs(
      title = sprintf("Figura 1 DIA: %s · %s (%s · %s)", input$dia_mapa_curso, input$dia_mapa_asig, input$dia_mapa_fecha, etapa_nombre),
      subtitle = sprintf("%d estudiantes evaluados | Rojo = eje temático que requiere refuerzo prioritario", n_estudiantes),
      x = NULL, y = NULL
    ) +
    tema_dash(10) +
    theme(
      axis.text.x = element_text(face = "bold", angle = 15, hjust = 1, size = 10),
      axis.text.y = element_text(size = 9.5),
      panel.grid = element_blank(),
      legend.position = "right"
    )
})

output$tabla_dia_apoyo <- renderTable({
  validate(need(dia_cargado(), "Sube archivos Excel del DIA."))
  r <- dia_filtrado()$res
  
  if (!is.null(input$select_curso) && input$select_curso != "TODOS") {
    r <- r %>% filter(Curso_Canon == input$select_curso | Curso == etiquetar(input$select_curso))
  }
  
  validate(need(nrow(r) > 0, "Sin registros para mostrar."))
  
  asis <- if (asist_cargada()) {
    asist_resumen() %>% transmute(Curso_Canon = Curso, Alumno_Canon = Nombre, Asist_Col = Pct)
  } else data.frame(Curso_Canon = character(), Alumno_Canon = character(), Asist_Col = numeric())
  
  notas <- if (notas_cargadas() && nrow(prom_base()) > 0) {
    prom_base() %>%
      mutate(Asig_Key = asig_clave(Asignatura)) %>%
      group_by(Curso_Canon = Curso, Alumno_Canon = Alumno, Asig_Key) %>%
      summarise(Nota_Col = round(mean(Promedio), 1), .groups = "drop")
  } else data.frame(Curso_Canon = character(), Alumno_Canon = character(), Asig_Key = character(), Nota_Col = numeric())
  
  r %>%
    mutate(Asig_Key = asig_clave(Asignatura)) %>%
    left_join(asis, by = c("Curso_Canon", "Alumno_Canon")) %>%
    left_join(notas, by = c("Curso_Canon", "Alumno_Canon", "Asig_Key")) %>%
    arrange(Promedio_Logro) %>%
    transmute(
      `Año-Mes` = paste0(Anio_Mes, " (", Etapa, ")"),
      Curso,
      Asignatura,
      Estudiante = Alumno_Canon,
      `Nivel DIA` = ifelse(is.na(Nivel_DIA), "-", Nivel_DIA),
      `Logro Prom.` = sprintf("%.1f%%", Promedio_Logro),
      `Eje más débil (Reforzar)` = sprintf("%s (%.0f%%)", Eje_Debil, Logro_Min),
      `Eje más fuerte` = sprintf("%s (%.0f%%)", Eje_Fuerte, Logro_Max),
      `Nota Colegio` = ifelse(is.na(Nota_Col), "-", sprintf("%.1f", Nota_Col)),
      `% Asist.` = ifelse(is.na(Asist_Col), "-", sprintf("%.1f%%", Asist_Col))
    )
  
}, striped = TRUE, hover = TRUE, bordered = TRUE)

# ------------------------------------------------------------------------------
# CONTROL DE CARGA
# Cobertura de datos por curso, estado de cada archivo y vinculación de alumnos entre fuentes.
# ------------------------------------------------------------------------------

output$tabla_cobertura <- renderTable({
  a <- if (asist_cargada()) {
    datos_globales() %>% group_by(Curso) %>% summarise(Asistencia = n_distinct(Nombre), .groups = "drop")
  } else data.frame(Curso = character(), Asistencia = integer())
  
  nd <- notas_data()
  n <- if (nrow(nd$det) + nrow(nd$prom) > 0) {
    bind_rows(nd$det[, c("Curso", "Asignatura")], nd$prom[, c("Curso", "Asignatura")]) %>%
      distinct() %>% count(Curso, name = "Notas")
  } else data.frame(Curso = character(), Notas = integer())
  
  p <- if (pdd_cargado()) {
    pdd_data() %>% group_by(Curso = Curso_Canon) %>% summarise(PDD = n_distinct(Asignatura), .groups = "drop")
  } else data.frame(Curso = character(), PDD = integer())
  
  di <- if (dia_cargado()) {
    dia_data()$res %>% group_by(Curso = Curso_Canon) %>% summarise(DIA = n_distinct(paste(Asignatura, Anio_Mes)), .groups = "drop")
  } else data.frame(Curso = character(), DIA = integer())
  
  cursos <- unique(c(a$Curso, n$Curso, p$Curso, di$Curso))
  validate(need(length(cursos) > 0, "Aún no has cargado archivos."))
  
  df <- data.frame(Curso = cursos, stringsAsFactors = FALSE) %>%
    left_join(a, by = "Curso") %>% left_join(n, by = "Curso") %>%
    left_join(p, by = "Curso") %>% left_join(di, by = "Curso")
  for (col in c("Asistencia", "Notas", "PDD", "DIA")) if (!col %in% names(df)) df[[col]] <- NA_integer_
  
  df %>%
    mutate(Etiqueta = etiquetar(Curso)) %>%
    arrange(Etiqueta) %>%
    transmute(Curso = Etiqueta,
              `Asistencia (alumnos)` = ifelse(is.na(Asistencia), "FALTA", as.character(Asistencia)),
              `Notas (asignaturas)` = ifelse(is.na(Notas), "FALTA", as.character(Notas)),
              `PDD (asignaturas)` = ifelse(is.na(PDD), "FALTA", as.character(PDD)),
              `DIA (evaluaciones)` = ifelse(is.na(DIA), "FALTA", as.character(DIA)))
  
}, striped = TRUE, hover = TRUE, bordered = TRUE)

output$tabla_archivos <- renderTable({
  ent <- c(unname(asistencia_parseada()), unname(notas_parseadas()),
           unname(pdd_parseada()), unname(dia_parseada()))
  validate(need(length(ent) > 0, "Aún no has cargado archivos."))
  df <- bind_rows(lapply(ent, function(e) {
    data.frame(Archivo = e$nombre, Tipo = e$tipo, Curso = e$curso_txt,
               Asignatura = e$asignatura, `Año` = e$anio, Semestre = e$semestre,
               Profesor = e$profesor, Alumnos = as.character(e$n_alumnos),
               `Notas / Evaluados` = as.character(e$n_notas),
               Estado = e$estado, Detalle = e$detalle,
               check.names = FALSE, stringsAsFactors = FALSE)
  }))
  df$Alumnos[is.na(df$Alumnos)] <- "-"
  df$`Notas / Evaluados`[is.na(df$`Notas / Evaluados`)] <- "-"
  df %>% arrange(match(Estado, c("Error", "Sin notas aún", "OK")), Tipo, Curso)
}, striped = TRUE, hover = TRUE, bordered = TRUE)

